    // Auto-ingest completed orders for Office 13B
    useEffect(() => {
        if (!selectedCustomer || selectedCustomer.name !== "Kho Trung Tâm" || !customerHistory || customerHistory.length === 0) {
            return;
        }

        let updatedStock = { ...stock13b };
        let newProcessed = [...processedOrders13b];
        let hasChanges = false;
        let messages: string[] = [];

        customerHistory.forEach((line: any) => {
            const status = (line.status || "").toUpperCase();
            if ((status === "COMPLETED" || status === "SHIPPED") && !newProcessed.includes(line.so_number)) {
                const code = line.product_code;
                const qty = line.quantity || 0;
                if (code && qty > 0) {
                    updatedStock[code] = (updatedStock[code] || 0) + qty;
                    newProcessed.push(line.so_number);
                    hasChanges = true;
                    messages.push(`Đã tự động nhập ${qty} sản phẩm (${line.item_name || code}) từ Đơn hàng ${line.so_number} vào Kho Trung Tâm.`);
                }
            }
        });

        if (hasChanges) {
            setStock13b(updatedStock);
            setProcessedOrders13b(newProcessed);
            messages.forEach(msg => showToast(msg, "success"));
        }
    }, [customerHistory, selectedCustomer]);

