    const allSalesProducts = useMemo(() => {
        const commCodes = new Set(commercialProducts.map(p => p.code));
        const comm = commercialProducts.map(p => ({
            code: p.code,
            parent_code: (p as any).parent_code || (p as any).parent_item_code || undefined,
            parent_item_code: (p as any).parent_code || (p as any).parent_item_code || undefined,
            name: p.name,
            brand: p.brand || "Thương mại",
            unit: p.unit || "Hộp",
            supplier: p.supplier || "",
            price: p.price,
            priceDealer1: p.priceDealer1 || Math.round(p.price * 0.9),
            priceDealer2: p.priceDealer2 || Math.round(p.price * 0.85),
            specification: p.specification || p.unit || "",
            category: p.category,
            category2: p.subCategory || "Khác",
            registrationNo: "",
            notes: p.notes || "",
            imageUrl: p.imageUrl || "",
            techSpecs: p.techSpecs || "",
            isEquipment: p.isEquipment || (p.category ? p.category.includes("Thiết bị") : false),
            configurations: p.configurations || [],
            isCommercial: true,
            badge: (p.brand === "ABT" || (p.code && (p.code.startsWith("SQH") || p.code.startsWith("EXS") || p.code.startsWith("LBC")))) ? "🧪 TBR / ABT" : `🛒 ${p.brand || "Thương mại"}`
        }));
        const mfg = biolabProducts
            .filter(p => !commCodes.has(p.code))
            .map(p => ({
                code: p.code,
                parent_code: (p as any).parent_code || (p as any).parent_item_code || undefined,
                parent_item_code: (p as any).parent_code || (p as any).parent_item_code || undefined,
                name: p.name,
                brand: (p as any).brand || "ABT",
                unit: (p as any).unit || "Hộp",
                supplier: "ABT",
                price: p.price,
                priceDealer1: p.priceDealer1,
                priceDealer2: p.priceDealer2,
                specification: p.specification || "",
                category: p.category || "Khác",
                category2: p.category2 || "Khác",
                registrationNo: p.registrationNo || "",
                notes: p.notes || "",
                imageUrl: (p as any).imageUrl || "",
                techSpecs: (p as any).techSpecs || "",
                isEquipment: (p as any).isEquipment || false,
                configurations: (p as any).configurations || [],
                isCommercial: false,
                badge: "🧪 TBR / ABT"
            }));
        const existingCodes = new Set([...comm.map(p => p.code), ...mfg.map(p => p.code)]);
        const dbItems = dbMasterProducts
            .filter(p => p.code && !existingCodes.has(p.code))
            .map(p => {
                const isMfg = p.manufacturer === "ABT" || p.manufacturer === "TBR" || (p.code && (p.code.startsWith("SQH") || p.code.startsWith("EXS") || p.code.startsWith("LBC") || p.code.startsWith("TBR")));
                // Tuyệt đối không lấy cost_price làm giá bán khi standard_price để trống (0)
                const priceNum = Number(p.standard_price) || 0;
                const costNum = Number(p.cost_price) || 0;
                return {
                    code: p.code,
                    parent_code: p.parent_code || p.parent_item_code || undefined,
                    parent_item_code: p.parent_code || p.parent_item_code || undefined,
                    name: p.name,
                    brand: p.manufacturer || (isMfg ? "ABT" : "Thương mại"),
                    unit: p.unit || "Hộp",
                    supplier: p.manufacturer || (isMfg ? "ABT" : "Thương mại"),
                    costPrice: costNum,
                    price: priceNum,
                    priceDealer1: priceNum > 0 ? Math.round(priceNum * 0.9) : 0,
                    priceDealer2: priceNum > 0 ? Math.round(priceNum * 0.85) : 0,
                    specification: p.specification || p.unit || "",
                    category: p.category || "Khác",
                    category2: p.category || "Khác",
                    registrationNo: "",
                    notes: p.storage_condition ? `Bảo quản: ${p.storage_condition}` : "",
                    imageUrl: "",
                    techSpecs: "",
                    isEquipment: (p.category ? p.category.includes("Thiết bị") : false) || (p.code ? p.code.startsWith("EQ-") : false),
                    configurations: [],
                    isCommercial: !isMfg,
                    badge: isMfg ? "🧪 TBR / ABT" : `🛒 ${p.manufacturer || "Thương mại"}`
                };
            });
        return [...comm, ...mfg, ...dbItems];
    }, [biolabProducts, commercialProducts, dbMasterProducts]);

    // Modal & Form states for Đơn hàng yêu cầu (Wholesale Orders)
