    // Tự động hoàn thành SO Stock khi tất cả mã hàng của đơn đã nhập kho từ PO (khi mã hàng cuối cùng nhập kho là tự động hoàn thành)
    useEffect(() => {
        if (!procurementOrders || procurementOrders.length === 0) return;
        setFactoryOrders(prev => {
            let hasChanges = false;
            const updated = prev.map(req => {
                const isStockOrder = Boolean(req.isStockOrder || req.orderCategory === "STOCK" || (req.id && String(req.id).includes("STOCK")));
                if (!isStockOrder) return req;
                if (req.status === "COMPLETED" || req.status === "Delivered") return req;
                const items = req.items || [];
                if (items.length === 0) return req;

                // Kiểm tra xem tất cả các mã hàng đã nhập kho chưa
                const areAllItemsReceived = items.every((it: any) => {
                    const icode = (it.productCode || it.product_code || it.code || "").trim().toLowerCase();
                    if (!icode) return true;
                    return procurementOrders.some((po: any) => {
                        const isDone = po.status === "COMPLETED" || po.status === "Received" || po.status === "DELIVERED";
                        if (!isDone) return false;
                        const isDirectPO = Boolean(
                            (req.procureOrderCode && po.po_code === req.procureOrderCode) ||
                            (req.prCode && ((po.notes && po.notes.includes(req.prCode)) || (Array.isArray(po.pr_ids) && po.pr_ids.includes(req.prCode)))) ||
                            (req.id && po.notes && po.notes.includes(req.id)) ||
                            (req.order_code && po.notes && po.notes.includes(req.order_code))
                        );
                        if (!isDirectPO) return false;
                        const containsItem = Array.isArray(po.items) && po.items.some((poi: any) => {
                            const pcode = (poi.product_code || poi.code || "").trim().toLowerCase();
                            return pcode && (pcode === icode || pcode.includes(icode) || icode.includes(pcode));
                        });
                        return containsItem;
                    });
                });

                if (areAllItemsReceived) {
                    hasChanges = true;
                    return {
                        ...req,
                        status: "COMPLETED",
                        procureStatus: "COMPLETED"
                    };
                }
                return req;
            });
            return hasChanges ? updated : prev;
        });
    }, [procurementOrders]);

    // Phase 2 VAT Request & Shipping Method States for SO (Yêu cầu 8 & 9)
    const [vatRequested, setVatRequested] = useState(false);
