    const [rmaNotes, setRmaNotes] = useState("");
    const [isSubmittingRma, setIsSubmittingRma] = useState(false);

    const [rmaList, setRmaList] = useState<any[]>([]);
    const [isRmaListModalOpen, setIsRmaListModalOpen] = useState(false);
