    // Phase 2 Partial Invoice Modal per Delivery Slip (Yêu cầu 9)
    const [partialInvoiceModalSlip, setPartialInvoiceModalSlip] = useState<{ order: any; slip: any } | null>(null);
    const [partialInvSelectedItems, setPartialInvSelectedItems] = useState<Record<string, boolean>>({});
    const [partialInvNo, setPartialInvNo] = useState("");
    const [partialInvDate, setPartialInvDate] = useState(() => todayVN());
    const [partialInvAmount, setPartialInvAmount] = useState(0);
    const [partialInvIsFinal, setPartialInvIsFinal] = useState(false);
