    const syncMissingCustomersToBackend = async (existingBackendCustomers: any[]) => {
        if (!apiBase) return;
        try {
            const headers: Record<string, string> = { "Content-Type": "application/json" };
            if (token) headers["Authorization"] = `Bearer ${token}`;

            // 1. Prepare wholesale / company customers
            const allWholesale = [...DEFAULT_COMPANY_CUSTOMERS];
            const localSaved = localStorage.getItem("sales_custom_customers");
            if (localSaved) {
                try {
                    const parsed = JSON.parse(localSaved);
                    if (Array.isArray(parsed)) {
                        parsed.forEach((p: any) => {
                            if (!allWholesale.some(w => w.customer_code === p.customer_code)) {
                                allWholesale.push(p);
                            }
                        });
                    }
                } catch (e) {}
            }

            const payloadList: any[] = [];
            for (const cust of allWholesale) {
                payloadList.push({
                    customer_code: cust.customer_code,
                    name: cust.name,
                    contact_person: cust.contact_person || null,
                    phone: cust.phone || null,
                    email: cust.email && cust.email.includes("@") ? cust.email : null,
                    address: cust.address || null,
                    region: cust.region || null,
                    tax_code: cust.tax_code || null,
                    sales_rep_id: cust.sales_rep_id || cust.salesRepId || null,
                    sales_rep_name: cust.sales_rep_name || cust.salesRepName || null,
                    contact_position: cust.contact_position || null,
                    contact_gender: cust.contact_gender || null,
                    contact_hometown: cust.contact_hometown || null,
                    contact_age: cust.contact_age ? Number(cust.contact_age) : null
                });
            }

            // 2. Prepare retail CRM customers (salesNvkdCustomers)
            let retailList = salesNvkdCustomers;
            const retailSaved = localStorage.getItem("sales_13b_nvkd_customers");
            if (retailSaved) {
                try {
                    const parsedRetail = JSON.parse(retailSaved);
                    if (Array.isArray(parsedRetail) && parsedRetail.length > 0) {
                        retailList = parsedRetail;
                    }
                } catch (e) {}
            }

            for (const rc of retailList) {
                const repName = salesPersonnel.find(p => p.employee_id === rc.salesRepId)?.full_name || rc.salesRepName || rc.salesRepId || null;
                payloadList.push({
                    customer_code: rc.id,
                    name: rc.name,
                    contact_person: rc.contact_person || rc.name,
                    phone: rc.phone && rc.phone !== "-" ? rc.phone : null,
                    email: rc.email && rc.email.includes("@") ? rc.email : null,
                    address: rc.address || null,
                    region: rc.region || "Khách hàng lẻ CRM",
                    tax_code: rc.taxCode || rc.tax_code || null,
                    sales_rep_id: rc.salesRepId || null,
                    sales_rep_name: repName,
                    contact_position: rc.position || rc.contact_position || "Khách lẻ",
                    contact_gender: rc.gender || rc.contact_gender || null,
                    contact_hometown: rc.hometown || rc.contact_hometown || null,
                    contact_age: rc.age ? Number(rc.age) : (rc.contact_age ? Number(rc.contact_age) : null)
                });
            }

            await fetch(`${apiBase}/api/v1/sales-orders/customers-sync-all`, {
                method: "POST",
                headers,
                body: JSON.stringify(payloadList)
            }).catch(() => {});
        } catch (err) {
            console.warn("Auto-sync customers to backend warning:", err);
        }
    };

    const fetchCustomers = async () => {
        try {
            // 1. Prioritize PostgreSQL Database directly via /api/sales?action=customers
            const res = await fetch("/api/sales?action=customers");
            if (res.ok) {
                const data = await res.json();
                if (data && Array.isArray(data.customers)) { // CSDL là nguồn chính: danh sách rỗng cũng là kết quả đúng
                    const parsedCusts = data.customers.map((c: any) => ({
                        ...c,
                        contacts: typeof c.contacts === "string" 
                            ? (() => { try { return JSON.parse(c.contacts); } catch(e) { return []; } })() 
                            : (Array.isArray(c.contacts) ? c.contacts : [])
                    }));
                    setCustomers(parsedCusts);
                    if (typeof window !== "undefined") {
                        localStorage.setItem("sales_custom_customers", JSON.stringify(parsedCusts));
                    }
                    return;
                }
            }
        } catch (e) {
            console.warn("Error fetching customers from /api/sales, trying fallback:", e);
        }

        // 2. Fallback to localStorage and defaults
        try {
            let merged = [...DEFAULT_COMPANY_CUSTOMERS];
            const localSaved = typeof window !== "undefined" ? localStorage.getItem("sales_custom_customers") : null;
            if (localSaved) {
                try {
                    const localArr = JSON.parse(localSaved);
                    if (Array.isArray(localArr) && localArr.length > 0) {
                        localArr.forEach((lc: any) => {
                            if (!merged.some((sc: any) => sc.customer_code === lc.customer_code || String(sc.id) === String(lc.id))) {
                                merged.push(lc);
                            }
                        });
                    }
                } catch (err) {}
            }
            if (merged.length > 0) {
                setCustomers(merged);
            }
        } catch (err) {
            if (DEFAULT_COMPANY_CUSTOMERS.length > 0) {
                setCustomers(DEFAULT_COMPANY_CUSTOMERS);
            }
        }
    };

    const fetchPersonnel = async () => {
        try {
            // Fetch real personnel & users from PostgreSQL database settings API
            const res = await fetch("/api/settings?action=overview");
            if (!res.ok) return;
            const data = await res.json();
            const rawPersonnel: any[] = Array.isArray(data.personnel) ? data.personnel : [];
            const rawUsers: any[] = Array.isArray(data.users) ? data.users : [];

            if (rawPersonnel.length === 0 && rawUsers.length === 0) return;

            // Map each real personnel from PostgreSQL table 'personnel'
            const mappedStaff = rawPersonnel
                .filter((p: any) => p.status === "ACTIVE" || !p.status)
                .map((p: any) => ({
                    id: p.id,
                    employee_id: p.employee_code || `NV-TBR-${String(p.id).padStart(3, "0")}`,
                    employee_code: p.employee_code || `NV-TBR-${String(p.id).padStart(3, "0")}`,
                    full_name: p.full_name,
                    department: p.department || "Kinh Doanh",
                    position: p.position || "Chuyên Viên Kinh Doanh",
                    email: p.email || "",
                    phone: p.phone || "",
                    is_active: p.status === "ACTIVE" || !p.status
                }));

            // Also include any active system users not already in personnel list
            const existingNames = new Set(mappedStaff.map((p: any) => String(p.full_name || "").trim().toLowerCase()));
            const mappedUsers = rawUsers
                .filter((u: any) => (u.status === "ACTIVE" || !u.status) && u.full_name && !existingNames.has(String(u.full_name).trim().toLowerCase()))
                .map((u: any) => ({
                    id: `U-${u.id}`,
                    employee_id: u.employee_code || `USER-${u.id}`,
                    employee_code: u.employee_code || `USER-${u.id}`,
                    full_name: u.full_name,
                    department: u.department || u.role || "Hệ Thống",
                    position: u.position || u.role || "Nhân Sự",
                    email: u.email || "",
                    phone: u.phone || "",
                    is_active: true
                }));

            const combinedCompanyStaff = [...mappedStaff, ...mappedUsers];
            setAllCompanyPersonnel(combinedCompanyStaff);

            // Filter for Sales & Leadership (or all relevant staff)
            const salesStaff = mappedStaff.filter((p: any) => {
                const dept = (p.department || "").toLowerCase();
                const pos = (p.position || "").toLowerCase();
                return dept.includes("kinh doanh") || dept.includes("sales") || 
                       dept.includes("ban giám đốc") || dept.includes("giám đốc") ||
                       pos.includes("kinh doanh") || pos.includes("sales") ||
                       pos.includes("giám đốc") || pos.includes("pm") || pos.includes("sản phẩm");
            });

            const finalList = salesStaff.length > 0 ? salesStaff : mappedStaff;

            setSalesPersonnel(finalList);

            if (typeof window !== "undefined") {
                localStorage.setItem("sales_personnel_custom", JSON.stringify(finalList));
            }

            const contactsMap: Record<string, { phone?: string; email?: string }> = {};
            combinedCompanyStaff.forEach((p: any) => {
                contactsMap[p.employee_id] = { phone: p.phone, email: p.email };
            });
            setSalesPersonnelContacts(contactsMap);
            if (typeof window !== "undefined") {
                localStorage.setItem("sales_personnel_contacts", JSON.stringify(contactsMap));
            }

            if (finalList.length > 0 && (!logEmployee || !finalList.some(p => p.employee_id === logEmployee))) {
                setLogEmployee(finalList[0].employee_id);
            }

            isPersonnelLoadedRef.current = true;
        } catch (err) {
            console.error("Failed to load real personnel from /api/settings:", err);
        }
    };

    // Pure function to immediately and synchronously build a customer's order history
    const computeCustomerHistory = (c: any, currentOrders: any[], currentSlips: any[]) => {
        if (!c) return [];
        const cName = (c.name || "").toLowerCase().trim();
        const cCode = (c.customer_code || c.customerCode || String(c.id || "")).toLowerCase().trim();
        const cTax = (c.tax_code || c.taxCode || "").toLowerCase().trim();

        const matchedOrders = (currentOrders || []).filter((fo: any) => {
            const foName = (fo.customerName || fo.customer_name || "").toLowerCase().trim();
            const foCustId = String(fo.customerId || fo.customer_id || "").toLowerCase().trim();
            const foCustCode = String(fo.customerCode || fo.customer_code || "").toLowerCase().trim();
            const foTax = String(fo.tax_code || fo.taxCode || "").toLowerCase().trim();

            const nameMatch = Boolean(cName && foName && (foName === cName || foName.includes(cName) || cName.includes(foName)));
            const codeMatch = Boolean(cCode && (
                foCustId === cCode || 
                foCustId === String(c.id || "").toLowerCase() || 
                (foCustCode && foCustCode === cCode)
            ));
            const taxMatch = Boolean(cTax && foTax && cTax === foTax);

            return nameMatch || codeMatch || taxMatch;
        });

        const foEntries = matchedOrders.map((fo: any) => {
            const totalAmount = fo.totalAmount || (fo.items || []).reduce((sum: number, it: any) => {
                const price = Number(it.unitPrice ?? it.unit_price ?? it.price) || 0;
                const qty = Number(it.quantity) || 1;
                return sum + (price * qty);
            }, 0);

            const linkedSlipForFo = (currentSlips || []).find((s: any) => 
                s.orderCode === fo.linkedSalesOrderId || 
                s.orderId === fo.id || 
                (fo.linkedSalesOrderId && s.orderCode?.includes(fo.linkedSalesOrderId))
            );

            let mappedStatus = "PENDING";
            if (fo.status === "Delivered" || fo.status === "Completed" || (linkedSlipForFo && linkedSlipForFo.isDelivered)) mappedStatus = "COMPLETED";
            else if (fo.status === "Ready" || fo.status === "Ordered") mappedStatus = "SHIPPED";
            else if (fo.status === "Approved") mappedStatus = "APPROVED";
            else if (fo.status === "Rejected") mappedStatus = "CANCELLED";

            return {
                order_id: fo.id,
                order_code: (fo.linkedSalesOrderId && fo.linkedSalesOrderId !== fo.id) ? `${fo.linkedSalesOrderId} (${fo.id})` : (fo.id || fo.linkedSalesOrderId),
                raw_code: fo.linkedSalesOrderId || fo.id,
                order_date: fo.createdAt || fo.createdDate || fo.requestedDeliveryDate || todayVN(),
                status: mappedStatus,
                raw_status: fo.status,
                total_amount: totalAmount,
                customer_name: fo.customerName || c.name,
                items: fo.items || [],
                is_factory_order: true,
                raw_order: fo,
                invoiceNo: fo.invoiceNo || linkedSlipForFo?.invoiceNo,
                invoiceDate: fo.invoiceDate || linkedSlipForFo?.deliveredAt,
                invoiceStatus: fo.invoiceStatus || (mappedStatus === "COMPLETED" ? "ISSUED" : undefined),
                deliveredAt: fo.deliveredAt || linkedSlipForFo?.deliveredAt,
                deliveryNotes: fo.deliveryNotes || linkedSlipForFo?.notes
            };
        });

        // Sắp xếp đơn mới nhất lên đầu
        foEntries.sort((a: any, b: any) => {
            const da = new Date(a.order_date).getTime() || 0;
            const db = new Date(b.order_date).getTime() || 0;
            return db - da;
        });

        return foEntries;
    };

    // Load customer purchase portfolio/history - ĐỒNG BỘ TỨC THÌ 0ms, KHÔNG CÓ ĐỘ TRỄ MẠNG
    const loadCustomerDetails = (c: any) => {
        if (!c) return;
        setSelectedCustomer(c);
        setCustomerSubTab("history");
        setCustContactSearch("");
        setCustContactRoleFilter("all");

        // Đồng bộ hiển thị đơn hàng NGAY LẬP TỨC (0ms) từ bộ nhớ hiện tại
        const instantHistory = computeCustomerHistory(c, factoryOrders, deliverySlips);
        setCustomerHistory(instantHistory);
    };

    // Auto synchronize customer purchase history whenever selectedCustomer, factoryOrders or delivery slips change
    useEffect(() => {
        if (selectedCustomer) {
            const updated = computeCustomerHistory(selectedCustomer, factoryOrders, deliverySlips);
            setCustomerHistory(updated);
        }
    }, [selectedCustomer, factoryOrders, deliverySlips]);

    const handleAttachmentUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        try {
            showToast(`Đang tải lên tệp "${file.name}"...`, "info");
            const data = await uploadSingleFileSmart(file);
            if (data.success && data.url) {
                const newAttachment = {
                    name: data.name || file.name,
                    size: data.size || file.size,
                    url: data.url
                };
                setTaskAttachments(prev => [...prev, newAttachment]);
                showToast(`Đã đính kèm tệp "${file.name}" thành công!`, "success");
            } else {
                showToast(data.error || "Tải tệp lên thất bại", "error");
            }
        } catch (err) {
            console.error("Attachment upload error:", err);
            showToast("Lỗi khi tải tệp lên máy chủ", "error");
        }
        e.target.value = "";
    };

