    // CRUD - Sales Tasks
    const handleSaveTask = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!taskTitle.trim()) {
            showToast("Vui lòng nhập tiêu đề công việc!", "warning");
            return;
        }

        // Auto-commit any pending draft in newTaskLogResult or newTaskLogAttachment so users never lose entered notes/files
        let currentLogs = [...taskLogs];
        if (newTaskLogResult.trim() || newTaskLogAttachment) {
            const pendingLog = {
                id: `l-${Date.now()}`,
                date: todayVN(),
                summary: newTaskLogResult.trim() || `Đính kèm tệp báo cáo: ${newTaskLogAttachment}`,
                attachment: newTaskLogAttachment || "",
                fileUrl: newTaskLogFileUrl || "",
                size: newTaskLogFileSize || ""
            };
            currentLogs = [pendingLog, ...currentLogs];
            setTaskLogs(currentLogs);
            setNewTaskLogResult("");
            setNewTaskLogAttachment("");
            setNewTaskLogFileUrl("");
            setNewTaskLogFileSize("");
        }

        const taskData = {
            task_id: editingTask ? editingTask.task_id : Date.now(),
            id: editingTask ? (editingTask.id || editingTask.task_id) : Date.now(),
            title: taskTitle.trim(),
            description: taskDesc || null,
            assignee_id: taskAssignee || null,
            status: taskStatus || "To Do",
            priority: taskPriority || "Medium",
            due_date: taskDueDate ? new Date(taskDueDate).toISOString() : null,
            objective: taskObjective || null,
            methodology: taskMethodology || null,
            results: taskResults || null,
            conclusion: (taskOutcome ? `[${taskOutcome}] ` : "") + (taskConclusion || ""),
            attachments: taskAttachments.length > 0 ? JSON.stringify(taskAttachments) : null,
            checklist: taskChecklist.length > 0 ? JSON.stringify(taskChecklist) : null,
            logs: currentLogs.length > 0 ? JSON.stringify(currentLogs) : null,
            created_at: editingTask ? (editingTask.created_at || new Date().toISOString()) : new Date().toISOString(),
            updated_at: new Date().toISOString()
        };

        // 1. Update local state & localStorage & Next.js /api/storage
        let updatedTasks: any[];
        if (editingTask) {
            const targetId = editingTask.task_id || editingTask.id;
            updatedTasks = tasks.map(t => {
                const matches = (t.task_id && String(t.task_id) === String(targetId)) ||
                                (t.id && String(t.id) === String(targetId));
                return matches ? { ...t, ...taskData } : t;
            });
        } else {
            updatedTasks = [taskData, ...tasks];
        }

        setTasks(updatedTasks);
        try {
            localStorage.setItem("sales_tasks", JSON.stringify(updatedTasks));
        } catch (storageErr) {
            console.warn("Could not save sales_tasks to localStorage (quota exceeded?):", storageErr);
        }

        fetch("/api/storage", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ key: "sales_tasks", data: updatedTasks })
        }).catch(err => console.error("Failed to sync sales_tasks to storage:", err));

        // 2. Also try backend API if available
        if (apiBase) {
            try {
                if (editingTask) {
                    fetch(`${apiBase}/api/v1/sales-ops/tasks/${editingTask.task_id}`, {
                        method: "PUT",
                        headers: {
                            "Content-Type": "application/json",
                            Authorization: `Bearer ${token}`
                        },
                        body: JSON.stringify(taskData)
                    }).catch(() => {});
                } else {
                    fetch(`${apiBase}/api/v1/sales-ops/tasks`, {
                        method: "POST",
                        headers: {
                            "Content-Type": "application/json",
                            Authorization: `Bearer ${token}`
                        },
                        body: JSON.stringify(taskData)
                    }).catch(() => {});
                }
            } catch (e) {}
        }

        showToast(editingTask ? "Đã cập nhật công việc!" : "Đã tạo công việc mới!", "success");

        // Activity notification for relevant employees
        const assigneeStaff = salesPersonnel.find(p => p.employee_id === taskAssignee);
        const assigneeName = assigneeStaff?.full_name || taskAssignee || "Nhân viên";
        const senderName = loggedInStaff?.full_name || user?.name || "Quản lý kinh doanh";
        if (editingTask) {
            notifyActivity({
                title: "Cập nhật công việc",
                message: `${senderName} đã cập nhật công việc "${taskTitle.trim()}" (Trạng thái: ${taskStatus}) cho ${assigneeName}.`,
                type: taskStatus === "Completed" ? "success" : "info",
                category: "task",
                sender: { name: senderName },
                targetEmployeeIds: taskAssignee ? [taskAssignee, "QL-03"] : ["QL-03"],
                targetEmployeeNames: [assigneeName],
                link: { tab: "sales", subTab: "tasks", itemId: String(taskData.id) }
            });
        } else {
            notifyActivity({
                title: "Giao việc mới",
                message: `${senderName} đã giao công việc mới "${taskTitle.trim()}" cho ${assigneeName}.`,
                type: "info",
                category: "task",
                sender: { name: senderName },
                targetEmployeeIds: taskAssignee ? [taskAssignee, "QL-03"] : ["QL-03"],
                targetEmployeeNames: [assigneeName],
                link: { tab: "sales", subTab: "tasks", itemId: String(taskData.id) }
            });
        }

        setIsTaskModalOpen(false);
        resetTaskForm();
    };

