    const openEditTaskModal = (t: any) => {
        setEditingTask(t);
        setTaskTitle(t.title);
        setTaskDesc(t.description || "");
        setTaskAssignee(t.assignee_id || "");
        setTaskStatus(t.status);
        setTaskPriority(t.priority);
        setTaskDueDate(t.due_date ? (/^\d{4}-\d{2}-\d{2}$/.test(String(t.due_date)) ? String(t.due_date) : toVNDateString(t.due_date)) : todayVN());
        setTaskObjective(t.objective || "");
        setTaskMethodology(t.methodology || "");
        setTaskResults(t.results || "");
        
        let outcome = "";
        let cleanConclusion = t.conclusion || "";
        if (cleanConclusion.startsWith("[Success]")) {
            outcome = "Success";
            cleanConclusion = cleanConclusion.substring(9);
        } else if (cleanConclusion.startsWith("[Failure]")) {
            outcome = "Failure";
            cleanConclusion = cleanConclusion.substring(9);
        }
        setTaskOutcome(outcome);
        setTaskConclusion(cleanConclusion);
        let parsedAttachments = [];
        if (t.attachments) {
            try {
                const parsed = JSON.parse(t.attachments);
                if (Array.isArray(parsed)) parsedAttachments = parsed;
            } catch (e) {
                console.error("Failed to parse task attachments:", e);
            }
        }
        setTaskAttachments(parsedAttachments);

        let parsedChecklist: any[] = [];
        if (t.checklist) {
            try {
                parsedChecklist = typeof t.checklist === "string" ? JSON.parse(t.checklist) : t.checklist;
                if (!Array.isArray(parsedChecklist)) parsedChecklist = [];
            } catch (e) {
                console.error("Failed to parse task checklist:", e);
            }
        }
        setTaskChecklist(parsedChecklist);

        let parsedLogs: any[] = [];
        if (t.logs) {
            try {
                parsedLogs = typeof t.logs === "string" ? JSON.parse(t.logs) : t.logs;
                if (!Array.isArray(parsedLogs)) parsedLogs = [];
            } catch (e) {
                console.error("Failed to parse task logs:", e);
            }
        }
        setTaskLogs(parsedLogs);
        setNewTaskLogResult("");
        setNewTaskLogAttachment("");
        setNewTaskLogFileUrl("");
        setNewTaskLogFileSize("");
        setTaskModalTab("checklist_logs");
        setIsTaskModalOpen(true);
    };

