    // Helper functions for Weekly Plan Approvals
    const getApproverTitle = (targetRepId: string) => {
        if (targetRepId === "KD-04" || targetRepId === "KD-05") {
            return "Quản lý Admin";
        }
        const isNvkdOrPm = ["KD-02", "KD-07", "KD-08", "KD-09", "KD-10", "KD-11", "KD-12"].includes(targetRepId);
        if (isNvkdOrPm) {
            return "Phó trưởng phòng KD (Huỳnh Thị Ngọc Huyền)";
        }
        return "PGĐ Kinh doanh (Đỗ Ngọc Diễm Trúc)";
    };

    const getWeeklyApproval = (week: number, repId: string): WeeklyApprovalRecord => {
        const id = `2026-W${week}-${repId}`;
        const existing = weeklyApprovals.find(a => a.id === id || (a.week === week && a.salesRepId === repId));
        if (existing) return existing;
        const rep = salesPersonnel.find(p => p.employee_id === repId);
        return {
            id,
            week,
            year: 2026,
            salesRepId: repId,
            salesRepName: rep ? rep.full_name : repId,
            status: "DRAFT"
        };
    };

    const handleSubmitWeeklyPlan = (week: number, repId: string) => {
        const id = `2026-W${week}-${repId}`;
        const rep = salesPersonnel.find(p => p.employee_id === repId);
        const repName = rep ? rep.full_name : (loggedInStaff?.full_name || repId);
        const approver = getApproverTitle(repId);
        
        setWeeklyApprovals(prev => {
            const index = prev.findIndex(a => a.id === id || (a.week === week && a.salesRepId === repId));
            const updated: WeeklyApprovalRecord = {
                id,
                week,
                year: 2026,
                salesRepId: repId,
                salesRepName: repName,
                status: "PENDING",
                submittedAt: new Date().toISOString()
            };
            if (index >= 0) {
                const copy = [...prev];
                copy[index] = { ...copy[index], ...updated };
                return copy;
            } else {
                return [...prev, updated];
            }
        });
        showToast(`Đã gửi kế hoạch Tuần ${week} lên ${approver} duyệt! Bạn vẫn có thể bổ sung lịch trình bất cứ lúc nào.`, "success");
        notifyActivity({
            title: "Gửi duyệt Kế hoạch tuần",
            message: `${repName} đã gửi Kế hoạch tuần ${week} lên ${approver} để phê duyệt.`,
            type: "info",
            category: "plan",
            sender: { name: repName, id: repId },
            targetEmployeeIds: ["NV-TBR-002", "NV-TBR-001"],
            targetEmployeeNames: ["Đỗ Ngọc Diễm Trúc", "Nguyễn Văn Hưng"],
            link: { tab: "sales", subTab: "planner" }
        });
    };

    const handleOpenReviewModal = (approval: WeeklyApprovalRecord, decision: "approve" | "reject") => {
        setReviewingApproval(approval);
        setReviewDecision(decision);
        setReviewFeedback(approval.reviewerFeedback || "");
        setIsReviewWeeklyModalOpen(true);
    };

    const handleExecuteReview = (e: React.FormEvent) => {
        e.preventDefault();
        if (!reviewingApproval) return;
        if (!can("sales.approve_orders")) {
            // Máy chủ cũng chặn quyết định duyệt của người không có quyền này
            showToast("Bạn chưa được cấp quyền duyệt kế hoạch (Duyệt Yêu Cầu Đặt Hàng / Kế Hoạch). Liên hệ Quản trị viên.", "error");
            return;
        }
        const isApproved = reviewDecision === "approve";
        
        setWeeklyApprovals(prev => {
            const index = prev.findIndex(a => a.id === reviewingApproval.id || (a.week === reviewingApproval.week && a.salesRepId === reviewingApproval.salesRepId));
            const updated: WeeklyApprovalRecord = {
                ...reviewingApproval,
                status: isApproved ? "APPROVED" : "REJECTED",
                reviewedAt: new Date().toISOString(),
                reviewerName: loggedInStaff?.full_name || "Trưởng phòng KD",
                reviewerFeedback: reviewFeedback.trim()
            };
            if (index >= 0) {
                const copy = [...prev];
                copy[index] = updated;
                return copy;
            } else {
                return [...prev, updated];
            }
        });
        setIsReviewWeeklyModalOpen(false);
        showToast(isApproved ? `Đã phê duyệt kế hoạch Tuần ${reviewingApproval.week} của ${reviewingApproval.salesRepName}!` : `Đã yêu cầu chỉnh sửa kế hoạch Tuần ${reviewingApproval.week}!`, isApproved ? "success" : "warning");
        notifyActivity({
            title: isApproved ? "Phê duyệt Kế hoạch tuần" : "Yêu cầu sửa Kế hoạch tuần",
            message: `${loggedInStaff?.full_name || "Quản lý"} đã ${isApproved ? "phê duyệt" : "yêu cầu sửa"} Kế hoạch tuần ${reviewingApproval.week} của bạn.${reviewFeedback ? ` Ghi chú: "${reviewFeedback.trim()}"` : ""}`,
            type: isApproved ? "success" : "warning",
            category: "plan",
            sender: { name: loggedInStaff?.full_name || "Quản lý" },
            targetEmployeeIds: [reviewingApproval.salesRepId],
            targetEmployeeNames: [reviewingApproval.salesRepName],
            link: { tab: "sales", subTab: "planner" }
        });
        setReviewingApproval(null);
        setReviewFeedback("");
    };

    // CRUD - Daily Logs
    const handleSaveLog = async (e: React.FormEvent) => {
        e.preventDefault();
        const empId = loggedInStaff?.employee_id || logEmployee || "KD-01";
        if (!logContent.trim()) {
            showToast("Vui lòng nhập nội dung công việc đã làm!", "warning");
            return;
        }

        const newLog = {
            log_id: Date.now(),
            id: Date.now(),
            date: todayVN(),
            employee_id: empId,
            sales_rep_id: empId,
            content: logContent.trim(),
            issues: logIssues ? logIssues.trim() : null,
            created_at: new Date().toISOString()
        };

        const updatedLogs = [newLog, ...dailyLogs];
        setDailyLogs(updatedLogs);
        localStorage.setItem("sales_daily_logs", JSON.stringify(updatedLogs));
        fetch("/api/storage", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ key: "sales_daily_logs", data: updatedLogs })
        }).catch(err => console.error("Failed to sync sales_daily_logs:", err));

        if (apiBase) {
            try {
                fetch(`${apiBase}/api/v1/sales-ops/logs`, {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`
                    },
                    body: JSON.stringify(newLog)
                }).catch(() => {});
            } catch (e) {}
        }

        showToast("Đã ghi nhật ký daily!", "success");
        setIsLogModalOpen(false);
        setLogContent("");
        setLogIssues("");
    };

    const handleDeleteLog = async (logId: number | string) => {
        if (!confirm("Xóa nhật ký này?")) return;
        const updatedLogs = dailyLogs.filter(l => l.log_id !== logId && l.id !== logId);
        setDailyLogs(updatedLogs);
        localStorage.setItem("sales_daily_logs", JSON.stringify(updatedLogs));
        fetch("/api/storage", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ key: "sales_daily_logs", data: updatedLogs })
        }).catch(err => console.error("Failed to sync sales_daily_logs deletion:", err));

        if (apiBase) {
            try {
                fetch(`${apiBase}/api/v1/sales-ops/logs/${logId}`, {
                    method: "DELETE",
                    headers: { Authorization: `Bearer ${token}` }
                }).catch(() => {});
            } catch (e) {}
        }

        showToast("Đã xóa nhật ký!", "success");
    };

    const handleSaveResult = async (plan: any, newStatus: string) => {
        const result = quickResults[plan.plan_id] || "";
        
        // 1. Update plan in state, localStorage, and storage API
        const updatedPlans = plans.map(p => {
            if (p.plan_id === plan.plan_id || p.id === plan.plan_id) {
                return { ...p, status: newStatus, result_summary: result };
            }
            return p;
        });
        setPlans(updatedPlans);
        localStorage.setItem("sales_plans", JSON.stringify(updatedPlans));
        fetch("/api/storage", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ key: "sales_plans", data: updatedPlans })
        }).catch(err => console.error("Failed to sync sales_plans result:", err));

        // 2. Auto generate execution log into dailyLogs
        const newLog = {
            log_id: Date.now(),
            id: Date.now(),
            date: todayVN(),
            employee_id: plan.assignee_id || "NV-001",
            sales_rep_id: plan.assignee_id || "NV-001",
            content: `[Kế hoạch tuần ${selectedWeek}] Cập nhật công việc: ${plan.task_name}\n- Dự án: ${plan.project_name || "Hoạt động chung"}\n- Trạng thái: ${newStatus === "Completed" ? "Đã hoàn thành" : newStatus === "In Progress" ? "Đang thực hiện" : "Chưa thực hiện"}\n- Kết quả: ${result || "Chưa có kết quả"}`,
            created_at: new Date().toISOString()
        };
        const updatedLogs = [newLog, ...dailyLogs];
        setDailyLogs(updatedLogs);
        localStorage.setItem("sales_daily_logs", JSON.stringify(updatedLogs));
        fetch("/api/storage", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ key: "sales_daily_logs", data: updatedLogs })
        }).catch(err => console.error("Failed to sync auto daily log:", err));

        // 3. Try backend async
        if (apiBase) {
            try {
                fetch(`${apiBase}/api/v1/sales-ops/plans/${plan.plan_id}`, {
                    method: "PUT",
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`
                    },
                    body: JSON.stringify({ status: newStatus, result_summary: result })
                }).catch(() => {});

                fetch(`${apiBase}/api/v1/sales-ops/logs`, {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`
                    },
                    body: JSON.stringify(newLog)
                }).catch(() => {});
            } catch (e) {}
        }

        showToast("Đã lưu tiến độ công việc và cập nhật nhật ký daily!", "success");
    };

    const saveCustomerLocally = (cust: any) => {
        setCustomers(prev => {
            const existsIndex = prev.findIndex(c => c.customer_code === cust.customer_code || String(c.id) === String(cust.id));
            let next;
            if (existsIndex >= 0) {
                next = [...prev];
                next[existsIndex] = { ...next[existsIndex], ...cust };
            } else {
                next = [cust, ...prev];
            }
            if (typeof window !== "undefined") {
                localStorage.setItem("sales_custom_customers", JSON.stringify(next));
            }
            return next;
        });
    };

    // Helper to resolve assigned sales rep for a customer
    const getCustomerAssignedRep = (c: any) => {
        if (c.sales_rep_id) return c.sales_rep_id;
        if (c.salesRepId) return c.salesRepId;
        if (c.sales_rep_name) {
            const trimmedName = c.sales_rep_name.trim().toLowerCase();
            const matchedStaff = salesPersonnel.find(p => 
                (p.full_name && p.full_name.trim().toLowerCase() === trimmedName) ||
                (p.name && p.name.trim().toLowerCase() === trimmedName) ||
                (p.full_name && trimmedName.includes(p.full_name.trim().toLowerCase()))
            );
            if (matchedStaff) return matchedStaff.employee_id || matchedStaff.employee_code;
            return c.sales_rep_name;
        }
        return "";
    };

    // CRUD - Customers
    const handleSaveCustomer = async (e: React.FormEvent) => {
        e.preventDefault();
        const codeTrimmed = custCode.trim();
        const nameTrimmed = custName.trim();

        if (!codeTrimmed || !nameTrimmed) {
            showToast("Vui lòng nhập đầy đủ Mã khách hàng và Tên khách hàng!", "warning");
            return;
        }

        setIsSavingCustomer(true);

        const emailVal = custEmail.trim();
        const validEmail = emailVal && emailVal.includes("@") && emailVal.includes(".") ? emailVal : null;

        const assignedRepId = isManagerOrAdmin 
            ? (custSalesRepId || loggedInStaff?.employee_id || salesPersonnel[0]?.employee_id || "NV-001") 
            : (loggedInStaff?.employee_id || custSalesRepId || salesPersonnel[0]?.employee_id || "NV-001");
        const assignedRepName = salesPersonnel.find(p => p.employee_id === assignedRepId)?.full_name || assignedRepId;

        const payload = {
            customer_code: codeTrimmed,
            name: nameTrimmed,
            tax_code: custTaxCode.trim() || null,
            contact_person: custContact.trim() || null,
            phone: custPhone.trim() || null,
            email: validEmail,
            address: custAddress.trim() || null,
            tax_address: custTaxAddress.trim() || null,
            delivery_address: custDeliveryAddress.trim() || custAddress.trim() || null,
            region: custRegion.trim() || null,
            province: custProvince.trim() || null,
            sales_rep_id: assignedRepId,
            sales_rep_name: assignedRepName,
            salesRepId: assignedRepId,
            salesRepName: assignedRepName,
            contact_position: custContactPosition.trim() || null,
            contact_gender: custContactGender.trim() || null,
            contact_hometown: custContactHometown.trim() || null,
            contact_age: custContactAge !== "" ? Number(custContactAge) : null,
            credit_limit: custCreditLimit,
            credit_term_days: custCreditTermDays,
            customer_type: custCustomerType,
            classification: custClassification.trim() || null,
            industry: custIndustry.trim() || null,
            special_price_list: custSpecialPriceList
        };

        const localCustomerObj = {
            id: editingCustomer ? editingCustomer.id : `CUST-LOCAL-${Date.now()}`,
            ...payload,
            customer_code: codeTrimmed,
            name: nameTrimmed,
            created_at: new Date().toISOString()
        };

        try {
            const res = await fetch("/api/sales?action=customer", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    id: typeof editingCustomer?.id === "number" ? editingCustomer.id : undefined,
                    ...payload
                })
            });

            if (res.ok) {
                const savedRes = await res.json();
                const savedCustomer = savedRes.customer || {
                    id: savedRes.id || (editingCustomer ? editingCustomer.id : Date.now()),
                    ...payload,
                    customer_code: codeTrimmed,
                    name: nameTrimmed,
                    created_at: new Date().toISOString()
                };

                // Update in-memory customer list immediately
                setCustomers(prev => {
                    const exists = prev.some(c => (editingCustomer && c.id === editingCustomer.id) || c.customer_code === codeTrimmed);
                    if (exists) {
                        return prev.map(c => ((editingCustomer && c.id === editingCustomer.id) || c.customer_code === codeTrimmed) ? { ...c, ...savedCustomer } : c);
                    }
                    return [savedCustomer, ...prev];
                });

                if (selectedCustomer && ((editingCustomer && selectedCustomer.id === editingCustomer.id) || selectedCustomer.customer_code === codeTrimmed)) {
                    setSelectedCustomer((prev: any) => prev ? { ...prev, ...savedCustomer } : savedCustomer);
                }

                showToast(editingCustomer ? "Đã sửa khách hàng thành công!" : "Đã thêm khách hàng mới thành công!", "success");
                setIsCustomerModalOpen(false);
                fetchCustomers();
                resetCustomerForm();
            } else {
                let errorMsg = "Lỗi khi lưu khách hàng lên máy chủ!";
                try {
                    const detail = await res.json();
                    if (typeof detail?.error === "string") errorMsg = detail.error;
                    else if (typeof detail?.detail === "string") errorMsg = detail.detail;
                } catch (e) {
                    errorMsg = `Lỗi máy chủ (${res.status})`;
                }
                showToast(`Không thể lưu khách hàng: ${errorMsg}`, "error");
            }
        } catch (err: any) {
            console.error("Network error saving customer to server:", err);
            showToast("Mất kết nối máy chủ, chưa lưu được dữ liệu khách hàng lên hệ thống! Vui lòng thử lại.", "error");
        } finally {
            setIsSavingCustomer(false);
        }
    };

    const handleDeleteCustomer = async (id: number | string) => {
        if (!window.confirm("Bạn có chắc chắn muốn xóa khách hàng này không? Mọi thông tin liên quan sẽ không thể phục hồi!")) {
            return;
        }
        try {
            const res = await fetch(`/api/sales?action=delete_customer`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ id })
            });
            if (!res.ok) {
                const errData = await res.json().catch(() => ({}));
                showToast(errData.error || "Không thể xóa khách hàng trên máy chủ!", "error");
                return;
            }
            setCustomers(prev => prev.filter(c => String(c.id) !== String(id)));
            if (selectedCustomer && String(selectedCustomer.id) === String(id)) {
                setSelectedCustomer(null);
            }
            showToast("Đã xóa khách hàng thành công!", "success");
            fetchCustomers();
        } catch (err) {
            console.error("Error deleting customer on server:", err);
            showToast("Mất kết nối máy chủ, chưa xóa được khách hàng!", "error");
        }
    };

