        setEditingContactIndex(index);
        setContactFormId(ct.id || "");
        setContactFormName(ct.name || "");
        setContactFormPosition(ct.position || "");
        setContactFormDepartment(ct.department || "");
        setContactFormPhone(ct.phone || "");
        setContactFormEmail(ct.email || "");
        setContactFormRoleType(ct.role_type || "Kỹ thuật / Quyết định mua");
