    const handleDeleteContact = async (contactIndex: number) => {
        if (!selectedCustomer) return;
        const currentContacts = Array.isArray(selectedCustomer.contacts) ? [...selectedCustomer.contacts] : [];
        const target = currentContacts[contactIndex];
        if (!target) return;

        if (!window.confirm(`Bạn có chắc chắn muốn xóa người liên hệ "${target.name}" không?`)) {
            return;
        }

        const updated = currentContacts.filter((_, idx) => idx !== contactIndex);
        
        // Update local state
        const updatedCustomer = { ...selectedCustomer, contacts: updated };
        setSelectedCustomer(updatedCustomer);
        setCustomers(prev => prev.map(c => (c.id === selectedCustomer.id || c.customer_code === selectedCustomer.customer_code) ? updatedCustomer : c));

        if (typeof window !== "undefined") {
            const saved = localStorage.getItem("sales_custom_customers");
            if (saved) {
                try {
                    const parsed = JSON.parse(saved);
                    if (Array.isArray(parsed)) {
                        const next = parsed.map((c: any) => (c.id === selectedCustomer.id || c.customer_code === selectedCustomer.customer_code) ? updatedCustomer : c);
                        localStorage.setItem("sales_custom_customers", JSON.stringify(next));
                    }
                } catch (e) {}
            }
        }

        // Call backend API
        try {
            await fetch("/api/sales?action=update_contacts", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    customer_id: typeof selectedCustomer.id === "number" ? selectedCustomer.id : undefined,
                    customer_code: selectedCustomer.customer_code,
                    contacts: updated
                })
            });
            showToast(`Đã xóa người liên hệ "${target.name}"!`, "success");
        } catch (err) {
            console.error("Failed to sync contact deletion:", err);
            showToast("Đã xóa trên giao diện.", "info");
        }
    };

    const handleSaveContactModal = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedCustomer) return;

        const nameTrimmed = contactFormName.trim();
        if (!nameTrimmed) {
            showToast("Vui lòng nhập họ tên người liên hệ!", "warning");
            return;
        }

        setIsSavingContact(true);
        try {
            const currentContacts = Array.isArray(selectedCustomer.contacts) ? [...selectedCustomer.contacts] : [];
            
            const newContactObj = {
                id: contactFormId || `CT-${selectedCustomer.customer_code || "KH"}-${Date.now().toString().slice(-4)}`,
                name: nameTrimmed,
                position: contactFormPosition.trim(),
                department: contactFormDepartment.trim(),
                phone: contactFormPhone.trim(),
                email: contactFormEmail.trim(),
                role_type: contactFormRoleType.trim() || "Kỹ thuật / Quyết định mua",
                is_primary: contactFormIsPrimary,
                notes: contactFormNotes.trim()
            };

            let updated: any[] = [];
            if (editingContactIndex !== null && editingContactIndex >= 0 && editingContactIndex < currentContacts.length) {
                updated = currentContacts.map((ct, idx) => {
                    if (idx === editingContactIndex) {
                        return newContactObj;
                    }
                    if (contactFormIsPrimary) {
                        return { ...ct, is_primary: false };
                    }
                    return ct;
                });
            } else {
                if (contactFormIsPrimary) {
                    updated = currentContacts.map(ct => ({ ...ct, is_primary: false }));
                    updated.unshift(newContactObj);
                } else {
                    updated = [...currentContacts, newContactObj];
                }
            }

            const updatedCustomer: any = { 
                ...selectedCustomer, 
                contacts: updated,
                ...(contactFormIsPrimary ? {
                    contact_person: nameTrimmed,
                    contact_position: contactFormPosition.trim(),
                    phone: contactFormPhone.trim() || selectedCustomer.phone,
                    email: contactFormEmail.trim() || selectedCustomer.email
                } : {})
            };

            setSelectedCustomer(updatedCustomer);
            setCustomers(prev => prev.map(c => (c.id === selectedCustomer.id || c.customer_code === selectedCustomer.customer_code) ? updatedCustomer : c));

            if (typeof window !== "undefined") {
                const saved = localStorage.getItem("sales_custom_customers");
                if (saved) {
                    try {
                        const parsed = JSON.parse(saved);
                        if (Array.isArray(parsed)) {
                            const next = parsed.map((c: any) => (c.id === selectedCustomer.id || c.customer_code === selectedCustomer.customer_code) ? updatedCustomer : c);
                            localStorage.setItem("sales_custom_customers", JSON.stringify(next));
                        }
                    } catch (e) {}
                }
            }

            // Sync to backend database
            await fetch("/api/sales?action=update_contacts", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    customer_id: typeof selectedCustomer.id === "number" ? selectedCustomer.id : undefined,
                    customer_code: selectedCustomer.customer_code,
                    contacts: updated
                })
            });

            showToast(editingContactIndex !== null ? "Đã cập nhật thông tin người liên hệ!" : "Đã thêm người liên hệ mới thành công!", "success");
            setIsContactModalOpen(false);
        } catch (err) {
            console.error("Failed to save contact:", err);
            showToast("Đã lưu thông tin người liên hệ trên giao diện!", "info");
            setIsContactModalOpen(false);
        } finally {
            setIsSavingContact(false);
        }
    };

