    const handleSaveIndustryGroup = async (e: React.FormEvent) => {
        e.preventDefault();
        const trimmedName = industryFormName.trim();
        if (!trimmedName) {
            showToast("Vui lòng nhập tên nhóm ngành hàng!", "warning");
            return;
        }

        setIsSavingIndustryGroup(true);
        try {
            let updatedGroups: any[];
            const isEditing = Boolean(editingIndustryGroup);
            const oldName = editingIndustryGroup?.name;

            if (isEditing && editingIndustryGroup) {
                updatedGroups = industryGroups.map(g => 
                    g.id === editingIndustryGroup.id 
                        ? { ...g, name: trimmedName, description: industryFormDesc.trim(), color: industryFormColor, badge: industryFormBadge }
                        : g
                );

                // If renamed, update all customers with oldName in state & database
                if (oldName && oldName !== trimmedName) {
                    setCustomers(prev => prev.map(c => {
                        let updated = { ...c };
                        if (c.industry === oldName) updated.industry = trimmedName;
                        if (c.classification === oldName) updated.classification = trimmedName;
                        return updated;
                    }));
                    if (selectedCustomer) {
                        setSelectedCustomer((prev: any) => {
                            if (!prev) return prev;
                            let updated = { ...prev };
                            if (prev.industry === oldName) updated.industry = trimmedName;
                            if (prev.classification === oldName) updated.classification = trimmedName;
                            return updated;
                        });
                    }
                    // Call backend to update classification & industry for customers in DB
                    fetch("/api/sales?action=rename_industry_group", {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ oldName, newName: trimmedName })
                    }).catch(err => console.error("Failed to rename customer industry batch:", err));
                }
            } else {
                // Check if already exists
                if (industryGroups.some(g => g.name.toLowerCase() === trimmedName.toLowerCase())) {
                    showToast("Tên nhóm ngành hàng này đã tồn tại!", "warning");
                    setIsSavingIndustryGroup(false);
                    return;
                }
                const newGroup: any = {
                    id: `ind_${Date.now()}`,
                    name: trimmedName,
                    description: industryFormDesc.trim(),
                    color: industryFormColor,
                    badge: industryFormBadge
                };
                updatedGroups = [...industryGroups, newGroup];
            }

            setIndustryGroups(updatedGroups);
            localStorage.setItem("sales_customer_industry_groups", JSON.stringify(updatedGroups));

            // Sync to backend storage
            await fetch("/api/storage?key=customer_industry_groups", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ key: "customer_industry_groups", data: updatedGroups })
            });

            showToast(isEditing ? `Đã cập nhật nhóm ngành "${trimmedName}"!` : `Đã tạo mới nhóm ngành "${trimmedName}"!`, "success");
            setEditingIndustryGroup(null);
            setIndustryFormName("");
            setIndustryFormDesc("");
        } catch (error) {
            console.error("Save industry group error:", error);
            showToast("Lỗi khi lưu thông tin nhóm ngành!", "error");
        } finally {
            setIsSavingIndustryGroup(false);
        }
    };

    const handleDeleteIndustryGroup = async (group: any) => {
        const affectedCount = customers.filter(c => c.industry === group.name || c.classification === group.name).length;
        const confirmMsg = affectedCount > 0
            ? `Nhóm "${group.name}" hiện đang có ${affectedCount} khách hàng. Bạn có chắc muốn xóa? Các khách hàng này sẽ được chuyển về "Chưa phân nhóm".`
            : `Bạn có chắc muốn xóa nhóm ngành "${group.name}"?`;

        if (!confirm(confirmMsg)) return;

        try {
            const updatedGroups = industryGroups.filter(g => g.id !== group.id);
            setIndustryGroups(updatedGroups);
            localStorage.setItem("sales_customer_industry_groups", JSON.stringify(updatedGroups));

            if (affectedCount > 0) {
                setCustomers(prev => prev.map(c => {
                    let updated = { ...c };
                    if (c.industry === group.name) updated.industry = "";
                    if (c.classification === group.name) updated.classification = "";
                    return updated;
                }));
                if (selectedCustomer) {
                    setSelectedCustomer((prev: any) => {
                        if (!prev) return prev;
                        let updated = { ...prev };
                        if (prev.industry === group.name) updated.industry = "";
                        if (prev.classification === group.name) updated.classification = "";
                        return updated;
                    });
                }
                fetch("/api/sales?action=rename_industry_group", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ oldName: group.name, newName: "" })
                }).catch(err => console.error("Failed to unassign classification in DB:", err));
            }

            await fetch("/api/storage?key=customer_industry_groups", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ key: "customer_industry_groups", data: updatedGroups })
            });

            showToast(`Đã xóa nhóm ngành "${group.name}"!`, "success");
            if (editingIndustryGroup?.id === group.id) {
                setEditingIndustryGroup(null);
                setIndustryFormName("");
                setIndustryFormDesc("");
            }
        } catch (error) {
            console.error("Delete industry group error:", error);
            showToast("Lỗi khi xóa nhóm ngành!", "error");
        }
    };

    const handleCreateInbound = (e: React.FormEvent) => {
        e.preventDefault();
        if (!inboundProductCode) {
            showToast("Vui lòng chọn sản phẩm / hàng hóa cần nhập kho!", "warning");
            return;
        }
        if (inboundQty <= 0) {
            showToast("Số lượng nhập kho phải lớn hơn 0!", "warning");
            return;
        }

        const prod = allSalesProducts.find(p => p.code === inboundProductCode);
        const receiverId = inboundReceiver || loggedInStaff?.employee_id || salesPersonnel[0]?.employee_id || "NV-001";
        const receiverName = salesPersonnel.find(p => p.employee_id === receiverId)?.full_name || receiverId;

        const now = new Date();
        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const prefix = `NK13B-${year}.${month}.`;
        const count = inboundLogs13b.filter(l => l.id.startsWith(prefix)).length + 1;
        const newId = `NK13B-${year}.${month}.${String(count).padStart(3, '0')}`;

        const finalUnitPrice = Number(inboundUnitPrice || (prod as any)?.costPrice || 0);
        const finalTotal = Number(inboundQty) * finalUnitPrice;

        const newLog: InboundLog13b = {
            id: newId,
            date: formatVNDate(now),
            type: inboundType,
            productCode: inboundProductCode,
            productName: prod?.name || inboundProductCode,
            category: prod?.category || (inboundType === "production" ? "Sản xuất ABT" : "Thương mại"),
            specification: prod?.specification || "",
            supplierName: inboundSupplier || (prod as any)?.supplier || (inboundType === "production" ? "Nhà máy ABT (MES)" : "Nhà cung cấp ngoài"),
            lotOrSerial: inboundLotOrSerial,
            expDate: inboundExpDate,
            quantity: Number(inboundQty),
            unitPrice: finalUnitPrice,
            totalAmount: finalTotal,
            invoiceNo: inboundInvoiceNo,
            receiverId: receiverId,
            receiverName: receiverName,
            notes: inboundNotes
        };

        // Increase stock13b
        setStock13b(prev => ({
            ...prev,
            [inboundProductCode]: (prev[inboundProductCode] || 0) + Number(inboundQty)
        }));

        setInboundLogs13b(prev => [newLog, ...prev]);
        showToast(`Đã tạo Phiếu nhập kho ${newId} và ghi tăng ${inboundQty} ${prod?.name || inboundProductCode} vào Kho 13B!`, "success");
        setIsInboundModalOpen(false);

        // Reset form
        setInboundProductCode("");
        setInboundProductSearchQuery("");
        setInboundSupplier("");
        setInboundLotOrSerial("");
        setInboundExpDate("");
        setInboundQty(1);
        setInboundUnitPrice(0);
        setInboundInvoiceNo("");
        setInboundNotes("");
    };

    const handleGiveStock = (e: React.FormEvent) => {
        e.preventDefault();
        if (!giveStockEmployee) {
            showToast("Vui lòng chọn nhân viên!", "warning");
            return;
        }

        const available = stock13b[giveStockProductCode] || 0;
        if (available < giveStockQty) {
            showToast(`Không đủ tồn kho trung tâm tại Kho Trung Tâm! Hiện chỉ còn ${available} sản phẩm.`, "error");
            return;
        }

        // Deduct from general stock
        const updatedGeneral = {
            ...stock13b,
            [giveStockProductCode]: available - giveStockQty
        };

        // Add to employee stock
        const empStock = nvkdStock13b[giveStockEmployee] || {};
        const updatedEmpStock = {
            ...empStock,
            [giveStockProductCode]: (empStock[giveStockProductCode] || 0) + giveStockQty
        };

        const updatedNvkd = {
            ...nvkdStock13b,
            [giveStockEmployee]: updatedEmpStock
        };

        setStock13b(updatedGeneral);
        setNvkdStock13b(updatedNvkd);

        const empName = salesPersonnel.find(p => p.employee_id === giveStockEmployee)?.full_name || giveStockEmployee;
        const prodName = allSalesProducts.find(p => p.code === giveStockProductCode)?.name || giveStockProductCode;

        // Sync stock reservation with TTL to PostgreSQL (Requirement 6)
        fetch("/api/sales?action=reserve_stock", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                order_code: `RES-${Date.now().toString().slice(-4)}`,
                customer_name: giveStockCustomerName.trim() || "Chưa xác định",
                sales_rep_name: empName,
                product_code: giveStockProductCode,
                product_name: prodName,
                quantity_reserved: giveStockQty,
                hold_until_date: giveStockHoldUntil,
                notes: `Giữ hàng cho ${empName} đến ${giveStockHoldUntil}`
            })
        }).then(async res => {
            if (!res.ok) {
                const err = await res.json().catch(() => ({}));
                showToast(`Chưa giữ chỗ được trong kho cho ${prodName}: ${err.error || res.status}`, "warning");
            }
        }).catch(e => console.error("Failed to reserve stock in PostgreSQL:", e));

        showToast(`Đã bàn giao ${giveStockQty} ${prodName} cho NVKD ${empName} (Giữ đến ${giveStockHoldUntil}).`, "success");
        setIsGiveStockModalOpen(false);
        setGiveStockQty(1);
        setGiveStockCustomerName("");
        fetchReservations();
    };

    // Inventory Reservations Handlers (Requirement 6 & 7)
    const handleCreateReservation = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!resProductCode || !resSalesRepId) {
            showToast("Vui lòng chọn sản phẩm và nhân viên Sales!", "warning");
            return;
        }
        setIsSubmittingReservation(true);
        try {
            const prod = allSalesProducts.find(p => p.code === resProductCode);
            const rep = salesPersonnel.find(p => p.employee_id === resSalesRepId);
            const repName = rep?.full_name || resSalesRepId;
            const prodName = prod?.name || resProductCode;

            const res = await fetch("/api/sales?action=reserve_stock", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    order_code: `RES-${Date.now().toString().slice(-5)}`,
                    customer_name: resCustomerName.trim() || "Chưa xác định",
                    sales_rep_name: repName,
                    product_code: resProductCode,
                    product_name: prodName,
                    quantity_reserved: Number(resQuantity) || 1,
                    hold_until_date: resHoldUntil,
                    notes: resNotes.trim() || `Giữ chỗ cho ${repName} đến ${resHoldUntil}`
                })
            });
            const data = await res.json();
            if (res.ok && data.success) {
                showToast(`Đã tạo giữ chỗ ${resQuantity} ${prodName} cho ${repName} thành công!`, "success");
                setIsCreateReservationModalOpen(false);
                setResProductCode("");
                setResCustomerName("");
                setResQuantity(1);
                setResNotes("");
                fetchReservations();
            } else {
                showToast("Lỗi khi tạo giữ chỗ: " + (data.error || ""), "error");
            }
        } catch (err: any) {
            showToast("Lỗi: " + err.message, "error");
        } finally {
            setIsSubmittingReservation(false);
        }
    };

    const handleReleaseReservation = async (item: any) => {
        if (!window.confirm(`Xác nhận giải phóng giữ chỗ ${item.quantity_reserved} cái mặt hàng [${item.product_code}] của Sales ${item.sales_rep_name} để trả lại tồn khả dụng ATP?`)) {
            return;
        }
        try {
            const res = await fetch("/api/sales?action=release_reservation", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    reservation_id: item.id,
                    reason: `Giải phóng bởi ${loggedInStaff?.full_name || "Quản trị"} - Trả lại kho ATP`,
                    actor: loggedInStaff?.full_name || "Quản trị viên"
                })
            });
            if (res.ok) {
                showToast(`Đã giải phóng giữ chỗ ID #${item.id} thành công!`, "success");
                fetchReservations();
            }
        } catch (e: any) {
            showToast("Lỗi khi giải phóng: " + e.message, "error");
        }
    };

    const handleRetailSale = (e: React.FormEvent) => {
        e.preventDefault();
        const repId = isManagerOrAdmin ? retailSaleEmployee : (loggedInStaff?.employee_id || salesPersonnel[0]?.employee_id);
        if (!repId) {
            showToast("Vui lòng chọn nhân viên thực hiện!", "warning");
            return;
        }

        const selectedCust = salesNvkdCustomers.find(c => String(c.id) === String(retailSaleCustomer)) || 
                             customers.find(c => String(c.id) === String(retailSaleCustomer));
        if (!selectedCust) {
            showToast("Vui lòng chọn khách hàng nhận hàng!", "warning");
            return;
        }

        if (retailSaleItems.length === 0) {
            showToast("Vui lòng khai báo ít nhất một sản phẩm!", "warning");
            return;
        }

        // Validate stock for all products first
        const empStock = nvkdStock13b[repId] || {};
        const tempStock = { ...empStock };
        const empName = salesPersonnel.find(p => p.employee_id === repId)?.full_name || repId;

        for (const item of retailSaleItems) {
            if (!item.productCode) {
                showToast("Vui lòng chọn sản phẩm!", "warning");
                return;
            }
            if (item.quantity <= 0) {
                showToast("Số lượng sản phẩm phải lớn hơn 0!", "warning");
                return;
            }
            const available = tempStock[item.productCode] || 0;
            if (available < item.quantity) {
                const prodName = biolabProducts.find(p => p.code === item.productCode)?.name || item.productCode;
                showToast(`NVKD ${empName} không đủ tồn kho ký gửi cho sản phẩm ${prodName}! Hiện chỉ còn giữ ${available} sản phẩm.`, "error");
                return;
            }
            // Temporarily deduct to handle duplicate product codes in different lines
            tempStock[item.productCode] -= item.quantity;
        }

        // Deduct from employee stock
        const updatedNvkd = {
            ...nvkdStock13b,
            [repId]: tempStock
        };

        // Create log entry
        const items = retailSaleItems.map(item => {
            const prod = biolabProducts.find(p => p.code === item.productCode);
            return {
                productCode: item.productCode,
                productName: prod?.name || item.productCode,
                quantity: item.quantity,
                price: item.price,
                total: item.quantity * item.price
            };
        });
        const total = items.reduce((sum, item) => sum + item.total, 0);

        const newLog = {
            id: `RT-${Date.now()}`,
            date: new Date().toISOString(),
            salesRepId: repId,
            salesRepName: empName,
            customerId: selectedCust.id,
            customerName: selectedCust.name,
            customerPhone: selectedCust.phone || "-",
            items: items,
            total: total
        };

        setNvkdStock13b(updatedNvkd);
        setRetailLogs13b(prev => [newLog, ...prev]);

        showToast(`Đã ghi nhận báo cáo bán lẻ thành công cho ${selectedCust.name}!`, "success");
        setIsRetailSaleModalOpen(false);
        setRetailSaleCustomer("");
        setRetailSaleCustomerPhone("");
        setRetailSaleItems([{ productCode: "", quantity: 1, price: 0 }]);
    };

    const normalizeComparableVN = (val: any): string => {
        if (!val) return "";
        return String(val)
            .normalize("NFC")
            .toLowerCase()
            .replace(/oà/g, "òa").replace(/oá/g, "óa").replace(/oả/g, "ỏa").replace(/oã/g, "õa").replace(/oạ/g, "ọa")
            .replace(/oè/g, "òe").replace(/oé/g, "óe").replace(/oẻ/g, "ỏe").replace(/oẽ/g, "õe").replace(/oẹ/g, "ọe")
            .replace(/uỳ/g, "ùy").replace(/uý/g, "úy").replace(/uỷ/g, "ủy").replace(/uỹ/g, "ũy").replace(/uỵ/g, "ụy")
            .replace(/\s+/g, " ")
            .trim();
    };

    const loggedInStaff = useMemo(() => {
        if (!user || !salesPersonnel || salesPersonnel.length === 0) return null;
        const uName = normalizeComparableVN(user.name || (user as any).full_name || "");
        const uEmail = (user.email || "").toLowerCase().trim();
        const uNameRaw = ((user as any).username || "").toLowerCase().trim();
        const uId = (user.id || "").toLowerCase().trim();
        const uEmpCode = String((user as any).employee_code || "").toLowerCase().trim();

        return salesPersonnel.find(p => {
            const pEmail = (p.email || "").toLowerCase().trim();
            const pName = normalizeComparableVN(p.full_name || "");
            const pEmpId = (p.employee_id || "").toLowerCase().trim();
            const pEmpCode = String((p as any).employee_code || "").toLowerCase().trim();

            if (pEmail && uEmail && pEmail === uEmail) return true;
            if (pName && uName && pName === uName) return true;
            if (pEmpId && (uId.includes(pEmpId) || uNameRaw.includes(pEmpId) || (uEmpCode && pEmpId === uEmpCode))) return true;
            if (pEmpCode && (uEmpCode === pEmpCode || uNameRaw === pEmpCode || uId.includes(pEmpCode))) return true;
            
            // Exact / specific mappings for linked accounts
            if (pEmpId === "kd-01" && (uNameRaw === "quan.kd" || uEmail.includes("phuongquan") || uName.includes("phương quân"))) return true;
            if (pEmpId === "kd-02" && (uNameRaw === "nhu.kd" || uEmail.includes("nnhu44063") || uName.includes("xuân như"))) return true;
            if (pEmpId === "kd-03" && (uNameRaw === "huyen.kd" || uEmail.includes("htnhuyen") || uName.includes("ngọc huyền") || uName.includes("ngoc huyen"))) return true;
            if (pEmpId === "kd-04" && (uNameRaw === "chau.kd" || uEmail.includes("yminhchau") || uName.includes("minh châu") || uName.includes("minh chau"))) return true;
            if (pEmpId === "kd-05" && (uNameRaw === "quynh.kd" || uEmail.includes("diquynh") || uName.includes("diễm quỳnh") || uName.includes("diem quynh"))) return true;
            if (pEmpId === "kd-06" && (uNameRaw === "thoa.kd" || uEmail.includes("tothoa") || uName.includes("kim thoa"))) return true;
            if (pEmpId === "kd-07" && (uNameRaw === "vy.kd" || uEmail.includes("thuyvy") || uName.includes("thúy vy") || uName.includes("thuy vy"))) return true;
            if (pEmpId === "kd-08" && (uNameRaw === "hhtruc.kd" || uNameRaw.includes("hhtruc") || uEmail.includes("hhtruc") || uName.includes("hoa trúc") || uName.includes("hoa truc"))) return true;
            if (pEmpId === "kd-09" && (uNameRaw === "anh.kd" || uEmail.includes("nhatanhtieu") || uName.includes("nhật anh") || uName.includes("nhat anh"))) return true;
            if (pEmpId === "kd-10" && (uNameRaw === "hinh.kd" || uEmail.includes("duchinh") || uName.includes("đức hinh") || uName.includes("duc hinh"))) return true;
            if (pEmpId === "kd-11" && (uNameRaw === "hanh.kd" || uEmail.includes("huynhhonghanh") || uName.includes("hồng hạnh") || uName.includes("hong hanh"))) return true;
            if (pEmpId === "kd-12" && (uNameRaw === "thao.kd" || uEmail.includes("sales01") || uName.includes("mai thảo") || uName.includes("mai thao"))) return true;
            if (pEmpId === "ql-03" && (uNameRaw === "truc.kd" || uNameRaw === "diemtruc.kd" || uEmail.includes("dongocdiemtruc") || uName.includes("diễm trúc") || uName.includes("diem truc"))) return true;
            return false;
        });
    }, [user, salesPersonnel]);

    // 1. Ban Giám Đốc & Admin hệ thống
    const isSalesExecutive = useMemo(() => {
        if (!user) return false;
        const role = (user.role || "").toLowerCase().trim();
        const dept = ((user as any).department || (user as any).dept || "").toLowerCase().trim();
        const email = (user.email || "").toLowerCase().trim();
        const name = (user.name || "").toLowerCase().trim();
        return role === "admin" || role === "director" || role === "vice_director" ||
               role.includes("giám đốc") || role.includes("director") ||
               dept.includes("ban giám đốc") || dept.includes("bgđ") || dept.includes("management") ||
               email === "admin@abtvn.com" || email === "ndkhanh@abt-vn.net" ||
               name.includes("khánh") || name.includes("khanh");
    }, [user]);

    // 2. Trưởng phòng / Phó phòng Kinh doanh (Chỉ BGĐ QL-03 và Phó trưởng phòng KD-03)
    const isSalesLeader = useMemo(() => {
        if (!user) return false;
        const role = (user.role || "").toLowerCase().trim();
        const pos = (loggedInStaff?.position || "").toLowerCase().trim();
        const email = (user.email || "").toLowerCase().trim();
        const name = (user.name || "").toLowerCase().trim();
        const uNameRaw = ((user as any).username || "").toLowerCase().trim();
        const empId = loggedInStaff?.employee_id;

        // PM, Admin Manager, Sale Admin and regular sales reps are NOT sales leaders
        if (role === "sales_pm" || pos.includes("pm") || pos.includes("quản lý sản phẩm") || 
            empId === "KD-01" || empId === "KD-06" || empId === "KD-04" || empId === "KD-05" ||
            empId === "KD-07" || empId === "KD-08" || empId === "KD-09" || empId === "KD-02" || empId === "KD-10" || empId === "KD-11" || empId === "KD-12" ||
            uNameRaw === "quan.kd" || uNameRaw === "thoa.kd" || uNameRaw === "chau.kd" || uNameRaw === "quynh.kd") {
            return false;
        }

        return isSalesExecutive ||
               empId === "KD-03" || empId === "QL-03" ||
               role === "sales_head" || role === "sales_deputy" ||
               role.includes("sales_head") || role.includes("sales_deputy") ||
               role.includes("phó phòng") || role.includes("trưởng phòng") ||
               pos.includes("trưởng phòng") || pos.includes("phó phòng") || pos.includes("phó trưởng phòng") ||
               uNameRaw === "huyen.kd" || uNameRaw.includes("htnhuyen") ||
               email === "htnhuyen1905@gmail.com" || email === "dongocdiemtruc@gmail.com" ||
               name.includes("huyền") || name.includes("diễm trúc");
    }, [user, loggedInStaff, isSalesExecutive]);

    // 3. Quản lý Admin (Admin Manager) - KD-01, KD-06
    const isAdminManager = useMemo(() => {
        if (!user) return false;
        const role = (user.role || "").toLowerCase().trim();
        const pos = (loggedInStaff?.position || "").toLowerCase().trim();
        const uNameRaw = ((user as any).username || "").toLowerCase().trim();
        const email = (user.email || "").toLowerCase().trim();
        const name = (user.name || "").toLowerCase().trim();
        const empId = loggedInStaff?.employee_id;

        // PM is NOT admin manager
        if (role === "sales_pm" || pos.includes("pm") || pos.includes("quản lý sản phẩm") || empId === "KD-08" || empId === "KD-09" || empId === "KD-07") {
            return false;
        }

        return empId === "KD-01" || empId === "KD-06" ||
               role === "sales_admin_manager" || role.includes("sales_admin_manager") || role.includes("admin manager") || role.includes("quản lý admin") ||
               pos.includes("admin manager") || pos.includes("quản lý admin") ||
               uNameRaw === "quan.kd" || uNameRaw === "thoa.kd" ||
               email.includes("phuongquan") || email.includes("tothoa") ||
               name.includes("phương quân") || name.includes("kim thoa");
    }, [user, loggedInStaff]);

    // 4. Nhân viên Sale Admin (Điều phối) - KD-04, KD-05
    const isSalesAdmin = useMemo(() => {
        if (!user) return false;
        const role = (user.role || "").toLowerCase().trim();
        const pos = (loggedInStaff?.position || "").toLowerCase().trim();
        const uname = ((user as any).username || "").toLowerCase().trim();
        const email = (user.email || "").toLowerCase().trim();
        const empId = loggedInStaff?.employee_id;

        // PM is NOT sales admin
        if (role === "sales_pm" || pos.includes("pm") || pos.includes("quản lý sản phẩm") || empId === "KD-08" || empId === "KD-09" || empId === "KD-07") {
            return false;
        }

        return isAdminManager ||
               empId === "KD-04" || empId === "KD-05" ||
               role === "sales_admin" || role.includes("sales admin") || role.includes("sale admin") || role.includes("sales_admin") ||
               pos.includes("sales admin") || pos.includes("sale admin") || pos.includes("điều phối") ||
               uname === "chau.kd" || uname === "quynh.kd" ||
               uname.includes("admin") || email.includes("admin");
    }, [user, loggedInStaff, isAdminManager]);

    const isManagerOrAdmin = useMemo(() => {
        return isSalesLeader || isAdminManager || isSalesAdmin;
    }, [isSalesLeader, isAdminManager, isSalesAdmin]);

    // Quyền đặc biệt: Nhân sự Kho Vận & Chuỗi Lạnh phụ trách giao hàng toàn bộ đơn hàng
    // Lưu ý: Nhân sự thuộc Phòng Kinh Doanh (sales_rep, sales_head, sales_admin, sales_pm) mặc định có quyền warehouse.view
    // để tra cứu tồn kho — tuyệt đối KHÔNG được xếp vào nhóm chỉ trực Kho Vận (isWarehouseStaff), nếu không sẽ bị ẩn nút Sửa/Copy/Hủy đơn!
    const isWarehouseStaff = useMemo(() => {
        if (!user && !loggedInStaff) return false;
        const role = (user?.role || loggedInStaff?.role || "").toLowerCase().trim();
        const dept = ((user as any)?.department || (user as any)?.dept || loggedInStaff?.department || "").toLowerCase().trim();
        const pos = (loggedInStaff?.position || "").toLowerCase().trim();
        const username = ((user as any)?.username || "").toLowerCase().trim();
        const empId = (loggedInStaff?.employee_id || "").toUpperCase();

        const isSalesOrExec =
            isSalesExecutive ||
            isManagerOrAdmin ||
            role.includes("sales") ||
            role === "admin" ||
            role === "director" ||
            role === "vice_director" ||
            dept.includes("kinh doanh") ||
            dept.includes("sales") ||
            dept.includes("ban giám đốc") ||
            empId.startsWith("KD-") ||
            empId.startsWith("QL-");
        if (isSalesOrExec) return false;

        return role === "warehouse" || role.includes("kho") || role.includes("thủ kho") || role.includes("logistics") ||
               dept.includes("kho") || dept.includes("warehouse") || dept.includes("logistics") ||
               pos.includes("kho") || pos.includes("thủ kho") || pos.includes("warehouse") || pos.includes("logistics") ||
               empId.startsWith("KV-") || empId.startsWith("KHO-") || empId === "NV-TBR-007" || username === "khoa.dpb";
    }, [user, loggedInStaff, isSalesExecutive, isManagerOrAdmin]);

    // Quyền chỉnh sửa thông tin đơn hàng (PBAC: sales.edit)
    const hasSalesEditPerm = useMemo(() => {
        return Boolean(can && can("sales.edit")) || Boolean(user?.permissions && (user.permissions as any)["sales.edit"]);
    }, [can, user]);

    // Nhân sự xem & phối hợp liên phòng ban (Kho Vận, Cung Ứng, Application, Pháp Chế được cấp quyền sales.view)
    const isCrossDepartmentViewer = useMemo(() => {
        if (!user && !loggedInStaff) return false;
        const dept = ((user as any)?.department || (user as any)?.dept || loggedInStaff?.department || "").toLowerCase().trim();
        const role = (user?.role || loggedInStaff?.role || "").toLowerCase().trim();
        const isSalesDept = dept.includes("kinh doanh") || dept.includes("sales") || role.includes("sales");
        const hasSalesPerm = Boolean(can && can("sales.view")) || Boolean(user?.permissions && (user.permissions as any)["sales.view"]);
        return (!isSalesDept && hasSalesPerm) || isWarehouseStaff;
    }, [user, loggedInStaff, can, isWarehouseStaff]);

    // Quyền phê duyệt Báo giá & Đơn hàng 0 đồng / Hàng tặng (cho phép phân quyền cho nhân sự ngoài BGĐ)
    const canApproveQuotations = useMemo(() => {
        return Boolean(
            isSalesExecutive ||
            isSalesLeader ||
            (can && (can("sales.approve_quotes") || can("sales.approve_zero_price") || can("sales.approve_discount")))
        );
    }, [isSalesExecutive, isSalesLeader, can]);

    const canApproveZeroPriceOrders = useMemo(() => {
        return Boolean(
            isSalesExecutive ||
            isSalesLeader ||
            (can && (can("sales.approve_zero_price") || can("sales.approve_quotes") || can("sales.approve_discount")))
        );
    }, [isSalesExecutive, isSalesLeader, can]);

    const canApproveSalesOrdersPerm = useMemo(() => {
        return Boolean(
            isManagerOrAdmin ||
            canApproveZeroPriceOrders ||
            (can && can("sales.approve_orders"))
        );
    }, [isManagerOrAdmin, canApproveZeroPriceOrders, can]);

    // Quyền xem Báo giá & Hợp đồng toàn bộ: Chỉ Ban Giám Đốc (QL-03), Phó trưởng phòng (KD-03), người được phân quyền duyệt Báo giá / Đơn 0đ, hoặc Kho Vận/Liên phòng ban để tra cứu đối soát
    const canViewAllQuotationsAndContracts = isSalesLeader || canApproveQuotations || canApproveZeroPriceOrders || isWarehouseStaff || isCrossDepartmentViewer;

    // Quyền xem toàn bộ hồ sơ khách hàng (bao gồm thông tin cá nhân riêng tư, sửa, xóa):
    // Chỉ Ban Giám Đốc (QL-03) và Phó trưởng phòng (KD-03) được xem toàn bộ.
    // Quản lý Admin (KD-01, KD-06), Sale Admin (KD-04, KD-05) và Kho Vận chỉ xem thông tin phục vụ giao nhận hàng (Địa chỉ, Mã KH, MST, Tên & SĐT người nhận hàng).
    const canViewAllCustomerFullDetails = isSalesLeader;

    // Quyền xem và điều phối toàn bộ Đơn hàng yêu cầu (Tab 6): Cả BGĐ, Trưởng phòng, Admin Manager, Sale Admin, người được phân quyền duyệt đơn/giá 0đ và Kho Vận đều được thao tác!
    const canManageAllOrders = isManagerOrAdmin || canApproveSalesOrdersPerm || isWarehouseStaff || isCrossDepartmentViewer;

    // Công nợ khách hàng: Kế toán & Quản trị viên (máy chủ kiểm tra lại quyền)
    const canViewCustomerDebt = Boolean(can && can("settings.view")) ||
        String((user as any)?.department || "").toLowerCase().includes("kế toán") ||
        String(user?.role || "").toLowerCase().includes("account");

    /** Đơn thuộc NVKD đang đăng nhập: theo mã nhân viên, hoặc theo họ tên NVKD lưu trên đơn (chuẩn hóa dấu tiếng Việt Thuỳ/Thùy). */
    const isOrderOfLoggedInStaff = (req: any): boolean => {
        if (!loggedInStaff && !user) return false;
        const reqRepId = String(req?.salesRepId || req?.sales_rep_id || "").trim().toUpperCase();
        const myEmpId = String(loggedInStaff?.employee_id || "").trim().toUpperCase();
        const myEmpCode = String((loggedInStaff as any)?.employee_code || (user as any)?.employee_code || "").trim().toUpperCase();
        const myUserId = String(user?.id || "").trim().toUpperCase();
        const myUsername = String((user as any)?.username || "").trim().toUpperCase();
        if (reqRepId && (reqRepId === myEmpId || reqRepId === myEmpCode || reqRepId === myUserId || reqRepId === myUsername)) {
            return true;
        }
        const repName = normalizeComparableVN(req?.salesRepName || req?.sales_rep_name || req?.sales_rep || req?.salesRep || "");
        const myStaffName = normalizeComparableVN(loggedInStaff?.full_name || "");
        const myUserName = normalizeComparableVN((user as any)?.full_name || user?.name || "");
        return Boolean(repName && ((myStaffName && repName === myStaffName) || (myUserName && repName === myUserName)));
    };

    // 5. Phân quyền Kế hoạch tuần chuyên biệt:
    // - PGĐ Kinh doanh / BGĐ / Admin (QL-03): Xem tất cả 13 nhân sự, duyệt cho Phó phòng, 2 Quản lý Admin, NVKD, PM
    const isViewerDirector = useMemo(() => {
        return isSalesExecutive || loggedInStaff?.employee_id === "QL-03";
    }, [isSalesExecutive, loggedInStaff]);

    // - Phó trưởng phòng KD (KD-03): Chỉ xem NVKD, PM và bản thân (không xem 2 Quản lý Admin, Sale Admin, PGĐ); gửi duyệt PGĐ
    const isViewerDeputy = useMemo(() => {
        if (isViewerDirector) return false;
        const role = (user?.role || "").toLowerCase();
        const pos = (loggedInStaff?.position || "").toLowerCase();
        const empId = loggedInStaff?.employee_id;
        return empId === "KD-03" || role === "sales_deputy" || role.includes("phó phòng") || pos.includes("phó phòng") || pos.includes("phó trưởng phòng");
    }, [isViewerDirector, user, loggedInStaff]);

    // - Quản lý Admin (KD-01, KD-06): Xem kế hoạch của nhau và của Sale Admin (không xem NVKD, PM, Phó phòng); duyệt cho Sale Admin; gửi duyệt PGĐ
    const isViewerAdminManager = useMemo(() => {
        if (isViewerDirector || isViewerDeputy) return false;
        const empId = loggedInStaff?.employee_id;
        const role = (user?.role || "").toLowerCase();
        const pos = (loggedInStaff?.position || "").toLowerCase();
        return empId === "KD-01" || empId === "KD-06" || role === "sales_admin_manager" || pos.includes("admin manager") || pos.includes("quản lý admin");
    }, [isViewerDirector, isViewerDeputy, user, loggedInStaff]);

    // Danh sách nhân sự được phép xem và điều hành (Công việc, Kế hoạch, Daily log) theo vai trò
    const visibleSalesPersonnel = useMemo(() => {
        if (!salesPersonnel || salesPersonnel.length === 0) return [];
        
        // 1. BGĐ & PGĐ Kinh doanh (QL-03): Xem tất cả 13 nhân sự
        if (isViewerDirector) {
            return salesPersonnel;
        }
        
        // 2. Phó trưởng phòng KD (KD-03): Chỉ xem NVKD, PM và bản thân (8 nhân sự: KD-03, KD-02, KD-07, KD-08, KD-09, KD-10, KD-11, KD-12)
        if (isViewerDeputy) {
            const allowedIds = ["KD-03", "KD-02", "KD-07", "KD-08", "KD-09", "KD-10", "KD-11", "KD-12"];
            return salesPersonnel.filter(p => allowedIds.includes(p.employee_id));
        }
        
        // 3. Quản lý Admin (KD-01, KD-06): Xem của nhau và của Sale Admin (4 nhân sự: KD-01, KD-06, KD-04, KD-05)
        if (isViewerAdminManager) {
            const allowedIds = ["KD-01", "KD-06", "KD-04", "KD-05"];
            return salesPersonnel.filter(p => allowedIds.includes(p.employee_id));
        }
        
        // 4. NVKD, PM, Sale Admin: Chỉ xem của chính mình
        const myId = loggedInStaff?.employee_id;
        if (myId) {
            const me = salesPersonnel.find(p => p.employee_id === myId);
            return me ? [me] : salesPersonnel.slice(0, 1);
        }
        
        return salesPersonnel.slice(0, 1);
    }, [salesPersonnel, isViewerDirector, isViewerDeputy, isViewerAdminManager, loggedInStaff]);

    const allowedPersonnelForWeeklyPlans = visibleSalesPersonnel;

    useEffect(() => {
        if (selectedAssigneeFilter !== "all" && visibleSalesPersonnel.length > 0) {
            const isAllowed = visibleSalesPersonnel.some(p => p.employee_id === selectedAssigneeFilter);
            if (!isAllowed) {
                setSelectedAssigneeFilter("all");
            }
        }
    }, [visibleSalesPersonnel, selectedAssigneeFilter]);

    // Helper kiểm tra quyền phê duyệt kế hoạch của đối tượng target
    const canApproveWeeklyPlan = (targetRepId: string) => {
        const myId = loggedInStaff?.employee_id;
        // Không thể tự duyệt kế hoạch của chính mình
        if (myId && targetRepId === myId) return false;

        // 1. PGĐ Kinh doanh / BGĐ / Admin duyệt cho tất cả
        if (isViewerDirector) {
            return true;
        }

        // 2. Phó trưởng phòng KD (KD-03) duyệt kế hoạch cho NVKD và PM
        if (isViewerDeputy) {
            const isNvkdOrPm = ["KD-02", "KD-07", "KD-08", "KD-09", "KD-10", "KD-11", "KD-12"].includes(targetRepId);
            return isNvkdOrPm;
        }

        // 3. Quản lý Admin duyệt cho Sale Admin (KD-04, KD-05)
        if (isViewerAdminManager) {
            return targetRepId === "KD-04" || targetRepId === "KD-05";
        }

        return false;
    };

    const canApproveFactoryOrders = useMemo(() => {
        return isSalesLeader || isAdminManager;
    }, [isSalesLeader, isAdminManager]);

    const maskPhone = (phone?: string) => {
        if (!phone || phone.trim() === "" || phone === "-") return "-";
        const cleaned = phone.trim();
        if (cleaned.length <= 4) return "****";
        return cleaned.slice(0, cleaned.length - 4) + "****";
    };

    const maskEmail = (email?: string) => {
        if (!email || email.trim() === "" || email === "-") return "-";
        const parts = email.trim().split("@");
        if (parts.length < 2) return "***@***";
        const name = parts[0];
        const domain = parts[1];
        const visibleName = name.length > 3 ? name.slice(0, 3) + "***" : "***";
        return `${visibleName}@${domain}`;
    };

    // Active stats employee ID based on role
    const activeNvkdId = useMemo(() => {
        if (isManagerOrAdmin) {
            return statsEmployeeFilter;
        }
        return loggedInStaff?.employee_id || salesPersonnel[0]?.employee_id || "";
    }, [isManagerOrAdmin, statsEmployeeFilter, loggedInStaff, salesPersonnel]);

    // All unique customer options extracted from quotations & contracts for dropdowns
    const allAvailableCustomersForQuotes = useMemo(() => {
        const set = new Set<string>();
        customers.forEach(c => { if (c.name) set.add(c.name); });
        quotations.forEach(q => { if (q.customerName) set.add(q.customerName); });
        return Array.from(set).sort((a, b) => a.localeCompare(b, "vi"));
    }, [customers, quotations]);

    const allAvailableCustomersForContracts = useMemo(() => {
        const set = new Set<string>();
        customers.forEach(c => { if (c.name) set.add(c.name); });
        contracts.forEach(c => { if (c.customerName) set.add(c.customerName); });
        return Array.from(set).sort((a, b) => a.localeCompare(b, "vi"));
    }, [customers, contracts]);

    // All available customer options for allocation (CRM wholesale, CRM retail, contracts, quotations)
    const allCustomerAllocationOptions = useMemo(() => {
        const list: CustomerAllocationOption[] = [];
        const seen = new Set<string>();

        (customers || []).forEach((c: any) => {
            const name = (c.name || "").trim();
            if (name && !seen.has(name.toLowerCase())) {
                seen.add(name.toLowerCase());
                list.push({
                    name,
                    code: c.customer_code || c.code || String(c.id || ""),
                    address: c.address || c.province || "",
                    region: c.region || "",
                    type: "CRM Sỉ"
                });
            }
        });

        (salesNvkdCustomers || []).forEach((c: any) => {
            const name = (c.name || "").trim();
            if (name && !seen.has(name.toLowerCase())) {
                seen.add(name.toLowerCase());
                list.push({
                    name,
                    code: c.customer_code || c.id || "",
                    address: c.address || "",
                    region: c.region || "",
                    type: "CRM Lẻ"
                });
            }
        });

        (contracts || []).forEach((c: any) => {
            const name = (c.partyBName || c.customerName || "").trim();
            if (name && !seen.has(name.toLowerCase())) {
                seen.add(name.toLowerCase());
                list.push({
                    name,
                    code: c.contract_code || c.id || "",
                    address: c.deliveryAddress || "",
                    type: "Hợp đồng"
                });
            }
        });

        (quotations || []).forEach((q: any) => {
            const name = (q.customerName || "").trim();
            if (name && !seen.has(name.toLowerCase())) {
                seen.add(name.toLowerCase());
                list.push({
                    name,
                    code: q.quote_code || q.id || "",
                    address: "",
                    type: "Báo giá"
                });
            }
        });

        return list.sort((a, b) => a.name.localeCompare(b.name, "vi"));
    }, [customers, salesNvkdCustomers, contracts, quotations]);

    // Helper function to match sales representative across ID, code, and full name
    const isRepMatch = (itemRepId?: string, itemRepName?: string, targetRepId?: string) => {
        if (!targetRepId || targetRepId === "all") return true;
        const normTarget = targetRepId.toLowerCase().trim();
        const normRepId = (itemRepId || "").toLowerCase().trim();
        const normRepName = (itemRepName || "").toLowerCase().trim();
        if (normRepId && normRepId === normTarget) return true;
        
        // Find staff by employee_id or employee_code or full_name
        const staff = (salesPersonnel || []).find((p: any) => 
            (p.employee_id && p.employee_id.toLowerCase() === normTarget) ||
            (p.employee_code && p.employee_code.toLowerCase() === normTarget)
        );
        if (staff) {
            const sName = (staff.full_name || "").toLowerCase().trim();
            const sCode = (staff.employee_code || "").toLowerCase().trim();
            const sId = (staff.employee_id || "").toLowerCase().trim();
            if (normRepName && sName && (normRepName.includes(sName) || sName.includes(normRepName))) return true;
            if (normRepId && (normRepId === sCode || normRepId === sId)) return true;
        }
        return false;
    };

    const toIsoDatePart = (raw: any): string => {
        const s = String(raw || "").trim();
        if (!s) return "";
        if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
        const m = s.match(/^(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})/);
        if (m) return `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;
        const d = parseLooseDate(s);
        if (d) {
            const yyyy = d.getFullYear();
            const mm = String(d.getMonth() + 1).padStart(2, "0");
            const dd = String(d.getDate()).padStart(2, "0");
            return `${yyyy}-${mm}-${dd}`;
        }
        return "";
    };

    // Helpers phân loại trạng thái duyệt Báo giá
    const checkQuoteHasZeroPrice = (q: any): boolean => {
        return Boolean(q?.hasZeroPriceItems || (Array.isArray(q?.items) && q.items.some((it: any) => Number(it?.unitPrice ?? it?.price ?? 0) === 0)));
    };
    const checkQuotePendingApproval = (q: any): boolean => {
        const hasZero = checkQuoteHasZeroPrice(q);
        const needsAppr = Boolean(hasZero || q?.requiresApproval || q?.priceApprovalStatus === "PENDING_APPROVAL");
        return Boolean(needsAppr && q?.priceApprovalStatus !== "APPROVED" && q?.status !== "Rejected");
    };
    const checkQuoteIsApproved = (q: any): boolean => {
        if (q?.status === "Rejected") return false;
        return !checkQuotePendingApproval(q);
    };

    // Danh sách báo giá cơ sở (đã lọc theo NVKD, KH, Mã, Thời gian, Từ khóa — chưa lọc theo Trạng thái duyệt để tính thống kê chính xác)
    const baseFilteredQuotationsList = useMemo(() => {
        return quotations.filter(q => {
            const userEmpId = loggedInStaff?.employee_id || (user as any)?.employee_id || (user as any)?.employee_code || "";
            const userFullName = loggedInStaff?.full_name || user?.name || "";
            const isOwner = Boolean(
                (userEmpId && isRepMatch(q.salesRepId, q.salesRepName, userEmpId)) ||
                (userFullName && q.salesRepName && (
                    q.salesRepName.toLowerCase().trim().includes(userFullName.toLowerCase().trim()) ||
                    userFullName.toLowerCase().trim().includes(q.salesRepName.toLowerCase().trim())
                ))
            );
            const canView = canViewAllQuotationsAndContracts || isOwner || true;
            if (!canView) return false;
            if (selectedAssigneeFilter !== "all" && !isRepMatch(q.salesRepId, q.salesRepName, selectedAssigneeFilter)) return false;
            if (filterQuoteRep !== "all" && !isRepMatch(q.salesRepId, q.salesRepName, filterQuoteRep)) return false;

            // Filter by Customer
            if (filterQuoteCustomer !== "all") {
                const targetCust = filterQuoteCustomer.trim().toLowerCase();
                const isMatchCust = (q.customerId && String(q.customerId).toLowerCase() === targetCust) ||
                                    (q.customer_code && q.customer_code.toLowerCase().includes(targetCust)) ||
                                    (q.customerName && q.customerName.toLowerCase().includes(targetCust)) ||
                                    (q.customer_name && q.customer_name.toLowerCase().includes(targetCust));
                if (!isMatchCust) return false;
            }

            // Filter by Quote Code
            if (filterQuoteCode.trim()) {
                const codeQuery = filterQuoteCode.trim().toLowerCase();
                if (!String(q.id || q.quotation_code || "").toLowerCase().includes(codeQuery)) return false;
            }

            // Filter by Date / Month / Custom Date Range
            if (filterQuoteDateMode !== "all") {
                const qIso = toIsoDatePart(q.date || q.created_at || q.createdAt);
                if (!qIso) return false;
                if (filterQuoteDateMode === "day" && filterQuoteSingleDate) {
                    if (qIso !== filterQuoteSingleDate) return false;
                } else if (filterQuoteDateMode === "month" && filterQuoteMonth) {
                    if (!qIso.startsWith(filterQuoteMonth)) return false;
                } else if (filterQuoteDateMode === "range") {
                    if (filterQuoteDateFrom && qIso < filterQuoteDateFrom) return false;
                    if (filterQuoteDateTo && qIso > filterQuoteDateTo) return false;
                }
            }

            // Shared search query
            if (searchQuoteContractQuery.trim()) {
                const query = searchQuoteContractQuery.trim().toLowerCase();
                const idMatch = String(q.id || q.quotation_code || "").toLowerCase().includes(query);
                const customerMatch = String(q.customerName || q.customer_name || "").toLowerCase().includes(query);
                const custCodeMatch = String(q.customer_code || "").toLowerCase().includes(query);
                const repMatch = String(q.salesRepName || q.sales_rep_name || "").toLowerCase().includes(query);
                const itemMatch = (q.items || []).some((it: any) => 
                    String(it.productCode || "").toLowerCase().includes(query) || 
                    String(it.productName || "").toLowerCase().includes(query)
                );
                return idMatch || customerMatch || custCodeMatch || repMatch || itemMatch;
            }
            return true;
        });
    }, [quotations, canViewAllQuotationsAndContracts, loggedInStaff, user, salesPersonnel, selectedAssigneeFilter, filterQuoteRep, filterQuoteCustomer, filterQuoteCode, filterQuoteDateMode, filterQuoteSingleDate, filterQuoteMonth, filterQuoteDateFrom, filterQuoteDateTo, searchQuoteContractQuery]);

    const quoteApprovalStats = useMemo(() => {
        let pendingCount = 0;
        let pendingValue = 0;
        let zeroPriceCount = 0;
        let approvedCount = 0;
        let draftCount = 0;
        let sentCount = 0;
        baseFilteredQuotationsList.forEach(q => {
            const isPend = checkQuotePendingApproval(q);
            const hasZero = checkQuoteHasZeroPrice(q);
            const isAppr = checkQuoteIsApproved(q);
            if (isPend) {
                pendingCount++;
                pendingValue += Number(q.totalAmount) || 0;
            }
            if (hasZero) zeroPriceCount++;
            if (isAppr) approvedCount++;
            if (q.status === "Draft") draftCount++;
            if (q.status === "Sent" || q.status === "Accepted") sentCount++;
        });
        return {
            total: baseFilteredQuotationsList.length,
            pendingCount,
            pendingValue,
            zeroPriceCount,
            approvedCount,
            draftCount,
            sentCount
        };
    }, [baseFilteredQuotationsList]);

    // Memoized filtered lists for Quotations and Contracts (Respecting TDZ)
    const filteredQuotationsList = useMemo(() => {
        if (filterQuoteApprovalStatus === "all") return baseFilteredQuotationsList;
        return baseFilteredQuotationsList.filter(q => {
            if (filterQuoteApprovalStatus === "pending_approval") return checkQuotePendingApproval(q);
            if (filterQuoteApprovalStatus === "approved") return checkQuoteIsApproved(q);
            if (filterQuoteApprovalStatus === "zero_price") return checkQuoteHasZeroPrice(q);
            if (filterQuoteApprovalStatus === "draft") return q.status === "Draft";
            if (filterQuoteApprovalStatus === "sent") return q.status === "Sent" || q.status === "Accepted";
            return true;
        });
    }, [baseFilteredQuotationsList, filterQuoteApprovalStatus]);

    const filteredContractsList = useMemo(() => {
        return contracts.filter(c => {
            const userEmpId = loggedInStaff?.employee_id || (user as any)?.employee_id || (user as any)?.employee_code || "";
            const userFullName = loggedInStaff?.full_name || user?.name || "";
            const isOwner = Boolean(
                (userEmpId && isRepMatch(c.salesRepId, c.salesRepName, userEmpId)) ||
                (userFullName && c.salesRepName && (
                    c.salesRepName.toLowerCase().trim().includes(userFullName.toLowerCase().trim()) ||
                    userFullName.toLowerCase().trim().includes(c.salesRepName.toLowerCase().trim())
                ))
            );
            const canView = canViewAllQuotationsAndContracts || isOwner || true;
            if (!canView) return false;
            if (selectedAssigneeFilter !== "all" && !isRepMatch(c.salesRepId, c.salesRepName, selectedAssigneeFilter)) return false;
            if (filterContractRep !== "all" && !isRepMatch(c.salesRepId, c.salesRepName, filterContractRep)) return false;

            // Filter by Customer
            if (filterContractCustomer !== "all") {
                const targetCust = filterContractCustomer.trim().toLowerCase();
                const isMatchCust = (c.customerId && String(c.customerId).toLowerCase() === targetCust) ||
                                    (c.customer_code && String(c.customer_code).toLowerCase().includes(targetCust)) ||
                                    (c.customerName && String(c.customerName).toLowerCase().includes(targetCust)) ||
                                    (c.customer_name && String(c.customer_name).toLowerCase().includes(targetCust));
                if (!isMatchCust) return false;
            }

            // Filter by Contract Code
            if (filterContractCode.trim()) {
                const codeQuery = filterContractCode.trim().toLowerCase();
                if (!String(c.id || c.contract_code || "").toLowerCase().includes(codeQuery)) return false;
            }

            // Shared search query
            if (searchQuoteContractQuery.trim()) {
                const query = searchQuoteContractQuery.trim().toLowerCase();
                const idMatch = String(c.id || c.contract_code || "").toLowerCase().includes(query);
                const titleMatch = String(c.contractTitle || c.title || "").toLowerCase().includes(query);
                const customerMatch = String(c.customerName || c.customer_name || "").toLowerCase().includes(query);
                const custCodeMatch = String(c.customer_code || "").toLowerCase().includes(query);
                const repMatch = String(c.salesRepName || c.sales_rep_name || "").toLowerCase().includes(query);
                const partyAMatch = String(c.partyAName || "").toLowerCase().includes(query) || String(c.partyARepresentative || "").toLowerCase().includes(query);
                const partyBMatch = String(c.partyBName || "").toLowerCase().includes(query) || String(c.partyBRepresentative || "").toLowerCase().includes(query);
                const itemMatch = (c.items || []).some((it: any) => 
                    String(it.productCode || "").toLowerCase().includes(query) || 
                    String(it.productName || "").toLowerCase().includes(query)
                );
                return idMatch || titleMatch || customerMatch || custCodeMatch || repMatch || partyAMatch || partyBMatch || itemMatch;
            }
            return true;
        });
    }, [contracts, canViewAllQuotationsAndContracts, loggedInStaff, user, salesPersonnel, selectedAssigneeFilter, filterContractRep, filterContractCustomer, filterContractCode, searchQuoteContractQuery]);

    const handleSaveNvkdCustomer = (e: React.FormEvent) => {
        e.preventDefault();
        if (!nvkdCustName.trim()) {
            showToast("Vui lòng nhập tên khách hàng lẻ!", "warning");
            return;
        }
        const repId = isManagerOrAdmin ? nvkdCustRepId : (loggedInStaff?.employee_id || salesPersonnel[0]?.employee_id);
        if (!repId) {
            showToast("Không xác định được nhân viên quản lý!", "error");
            return;
        }
        const repName = salesPersonnel.find(p => p.employee_id === repId)?.full_name || repId;

        const payload = {
            id: nvkdCustCode.trim() || (editingNvkdCustomer ? editingNvkdCustomer.id : `RC-${Date.now()}`),
            name: nvkdCustName.trim(),
            contact_person: nvkdCustContactPerson.trim() || nvkdCustName.trim(),
            phone: nvkdCustPhone.trim() || "-",
            email: nvkdCustEmail.trim() || null,
            address: nvkdCustAddress.trim() || null,
            taxAddress: nvkdCustTaxAddress.trim() || null,
            tax_address: nvkdCustTaxAddress.trim() || null,
            salesRepId: repId,
            salesRepName: repName,
            region: nvkdCustRegion || "Khách hàng lẻ CRM",
            taxCode: nvkdCustTaxCode.trim() || null,
            position: nvkdCustPosition.trim() || "Khách lẻ",
            gender: nvkdCustGender || null,
            hometown: nvkdCustHometown.trim() || null,
            age: nvkdCustAge !== "" ? Number(nvkdCustAge) : null
        };

        if (editingNvkdCustomer) {
            setSalesNvkdCustomers(prev => prev.map(c => c.id === editingNvkdCustomer.id ? payload : c));
            showToast("Đã cập nhật khách hàng lẻ thành công!", "success");
        } else {
            setSalesNvkdCustomers(prev => [...prev, payload]);
            showToast("Đã thêm khách hàng lẻ mới thành công!", "success");
        }

        // Sync to internal PostgreSQL DB via /api/sales so Tab 6 (Đơn hàng) immediately receives the updated customer
        const customerBody = {
            action: "customer",
            customer_code: payload.id,
            name: payload.name,
            contact_person: payload.contact_person,
            phone: payload.phone !== "-" ? payload.phone : null,
            email: payload.email,
            address: payload.address,
            tax_address: payload.tax_address,
            region: payload.region,
            tax_code: payload.taxCode,
            sales_rep_id: repId,
            sales_rep_name: repName,
            contact_position: payload.position,
            contact_gender: payload.gender,
            contact_hometown: payload.hometown,
            contact_age: payload.age
        };
        fetch("/api/sales?action=customer", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(customerBody)
        }).then(async res => {
            if (!res.ok) {
                console.error("Failed to save retail customer to /api/sales:", res.status);
            } else {
                fetchCustomers();
            }
        }).catch(err => console.warn("Failed to sync retail customer to /api/sales:", err));

        if (apiBase) {
            const headers: Record<string, string> = { "Content-Type": "application/json" };
            if (token) headers["Authorization"] = `Bearer ${token}`;
            fetch(`${apiBase}/api/v1/sales-orders/customers`, {
                method: "POST",
                headers,
                body: JSON.stringify(customerBody)
            }).catch(err => console.warn("Failed to sync retail customer to external MES:", err));
        }

        setIsNvkdCustomerModalOpen(false);
        resetNvkdCustomerForm();
    };

