    const isEquipmentProduct = (prod: any, nameOrCode?: string) => {
        if (!prod && !nameOrCode) return false;
        if (prod?.isEquipment === true) return true;
        if (prod?.isEquipment === false) return false;

        const cat = (prod?.category || "").toLowerCase();
        const str = `${prod?.name || ""} ${prod?.code || ""} ${nameOrCode || ""}`.toLowerCase();

        // Chặn tuyệt đối không nhận diện nhầm Hóa chất, Thuốc thử, Thuốc nhuộm, Kit test
        const nonEquipWords = ["kit", "thuốc nhuộm", "hóa chất", "sinh phẩm", "môi trường", "dung dịch", "gel", "primer", "probe", "test/hộp", "50 test", "100 test", "vật tư tiêu hao"];
        const isReagent = nonEquipWords.some(w => str.includes(w) || cat.includes(w));
        if (isReagent && !str.includes("máy") && !str.includes("hệ thống") && !str.includes("tủ")) {
            return false;
        }

        if (cat.includes("thiết bị") && !cat.includes("vật tư")) return true;
        if (prod?.configurations && Array.isArray(prod.configurations) && prod.configurations.length > 0) return true;

        const keywords = ["máy", "tủ an toàn", "tủ cấy", "tủ ấm", "nồi hấp", "ly tâm", "spectrophotometer", "shaker", "vortex", "kính hiển vi", "kingfisher", "cfx96", "gentier", "generotex", "libex"];
        return keywords.some(k => str.includes(k));
    };

