    // 2. Export Quotations Product Items Detail (Excel)
    const handleExportQuotationsItems = (targetQuotes?: any[]) => {
        const source = targetQuotes || (selectedQuoteIdsForExport.length > 0 
            ? filteredQuotationsList.filter(q => selectedQuoteIdsForExport.includes(q.id))
            : filteredQuotationsList);

        if (source.length === 0) {
            showToast("Không có báo giá nào để xuất chi tiết hàng hóa!", "warning");
            return;
        }

        const rows: any[] = [];
        let stt = 1;
        source.forEach(q => {
            (q.items || []).forEach((it: any) => {
                const qty = Number(it.quantity) || 0;
                const price = Number(it.price) || 0;
                const vatRate = it.vatRate !== undefined ? Number(it.vatRate) : 8;
                const priceBeforeVat = it.priceBeforeVat !== undefined ? Number(it.priceBeforeVat) : (vatRate > 0 ? Math.round(price / (1 + vatRate / 100)) : price);
                const totalBeforeVat = it.totalBeforeVat !== undefined ? Number(it.totalBeforeVat) : (qty * priceBeforeVat);
                const discountRate = Number(it.discountRate !== undefined ? it.discountRate : it.discountPercent) || 0;
                const discountAmount = it.discountAmount !== undefined ? Number(it.discountAmount) : Math.round(totalBeforeVat * (discountRate / 100));
                const lineTotal = qty * price; // Thành tiền báo khách = SL × Đơn giá sau VAT (CK tính riêng, không trừ vào BG)

                const prod = allSalesProducts.find(p => p.code === it.productCode) || biolabProducts.find(p => p.code === it.productCode);
                const effectiveParentCode = it.parentCode || it.parent_code || (prod as any)?.parent_code || (prod as any)?.parent_item_code;
                const displayCode = effectiveParentCode || it.productCode || "—";
                const rawNote = it.notes || it.note || "";
                const note = (rawNote === prod?.notes || rawNote === "Imported from Excel") ? "" : rawNote;

                rows.push({
                    "STT": stt++,
                    "Mã Báo Giá": q.id,
                    "Ngày Báo Giá": q.date ? formatVNDate(q.date) : "",
                    "Khách Hàng": q.customerName || "—",
                    "NVKD Phụ Trách": q.salesRepName || "—",
                    "Mã Sản Phẩm": displayCode,
                    "Mã Công Thức / SX": (effectiveParentCode && effectiveParentCode !== it.productCode) ? it.productCode : "—",
                    "Tên Hàng Hóa / Sản Phẩm": it.productName || "—",
                    "Hãng Sản Xuất": formatSupplierShortName(it.manufacturer || getProductManufacturer(it)),
                    "Quy Cách": it.specification || getProductSpecification(it),
                    "Đơn Vị Tính": it.unit || "Bộ / Hộp",
                    "Số Lượng": qty,
                    "Đơn Giá Sau VAT (Báo Khách)": price,
                    "% VAT": `${vatRate}%`,
                    "Đơn Giá Trước VAT": priceBeforeVat,
                    "Thành Tiền Trước VAT": totalBeforeVat,
                    "Chiết Khấu (%)": discountRate,
                    "Tiền Chiết Khấu (Trước VAT)": discountAmount,
                    "Thành Tiền Sau VAT": lineTotal,
                    "Ghi Chú SP": note
                });
            });
        });

        if (rows.length === 0) {
            showToast("Các báo giá được chọn chưa có chi tiết sản phẩm!", "warning");
            return;
        }

        const worksheet = XLSX.utils.json_to_sheet(rows);
        worksheet["!cols"] = [
            { wch: 6 },  // STT
            { wch: 16 }, // Mã Báo Giá
            { wch: 14 }, // Ngày Báo Giá
            { wch: 35 }, // Khách Hàng
            { wch: 22 }, // NVKD
            { wch: 16 }, // Mã SP
            { wch: 16 }, // Mã SX
            { wch: 42 }, // Tên Hàng Hóa
            { wch: 18 }, // Hãng SX
            { wch: 20 }, // Quy Cách
            { wch: 14 }, // ĐVT
            { wch: 10 }, // Số Lượng
            { wch: 22 }, // Đơn Giá Sau VAT
            { wch: 12 }, // % VAT
            { wch: 20 }, // Đơn Giá Trước VAT
            { wch: 22 }, // Thành Tiền Trước VAT
            { wch: 14 }, // Chiết Khấu (%)
            { wch: 22 }, // Tiền Chiết Khấu
            { wch: 22 }, // Thành Tiền Sau VAT
            { wch: 24 }  // Ghi Chú
        ];

        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, "Hàng Hóa Báo Giá");
        const fileName = `Hang_hoa_bao_gia_${formatVNDate(new Date()).replace(/\//g, "-")}.xlsx`;
        XLSX.writeFile(workbook, fileName);
        showToast(`Đã xuất ${rows.length} dòng hàng hóa từ ${source.length} báo giá ra Excel!`, "success");
        setIsQuoteExportMenuOpen(false);
    };

