            partyATaxCode: contractPartyATaxCode,
            partyACustomFields: contractPartyACustomFields,
            partyBName: contractPartyBName,
            partyBAddress: contractPartyBAddress,
            partyBPhone: contractPartyBPhone,
            partyBEmail: contractPartyBEmail,
            partyBRepresentative: contractPartyBRepresentative,
            partyBRole: contractPartyBRole,
            partyBTaxCode: contractPartyBTaxCode,
            partyBCustomFields: contractPartyBCustomFields,

            customerName: contractPartyBName || customerName,
            contractTitle: contractTitle,
            taxCode: contractPartyBTaxCode || contractTaxCode,
            representative: contractPartyBRepresentative || contractRepresentative,
            items: items,
