    const handleDeleteAppRequest = (reqId: string) => {
        if (!confirm(`Bạn có chắc muốn hủy yêu cầu phối hợp ${reqId}?`)) return;
        const targetReq = sharedAppRequests.find(r => r.id === reqId);
        const updated = sharedAppRequests.filter(r => r.id !== reqId);
        setSharedAppRequests(updated);
        if (typeof window !== "undefined") {
            localStorage.setItem("shared_app_requests", JSON.stringify(updated));
            fetch("/api/storage?key=shared_app_requests", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(updated)
            }).catch(() => {});

            // Also delete corresponding task in lab_app_tasks
            const storedTasks = localStorage.getItem("lab_app_tasks");
            if (storedTasks) {
                try {
                    const parsedTasks = JSON.parse(storedTasks);
                    if (Array.isArray(parsedTasks)) {
                        const linkedTitle = targetReq?.title && targetReq?.customerName
                            ? `[Sales - ${targetReq.customerName}] ${targetReq.title}`
                            : null;
                        const updatedTasks = parsedTasks.filter((t: any) => {
                            if (t.salesReqId === reqId || t.sharedReqId === reqId || t.id === reqId) return false;
                            // Task cũ chưa có liên kết salesReqId: chỉ khớp đúng tiêu đề đầy đủ do Sales tạo ra
                            if (!t.salesReqId && linkedTitle && t.title === linkedTitle) return false;
                            return true;
                        });
                        localStorage.setItem("lab_app_tasks", JSON.stringify(updatedTasks));
                        fetch("/api/storage?key=lab_app_tasks", {
                            method: "POST",
                            headers: { "Content-Type": "application/json" },
                            body: JSON.stringify(updatedTasks)
                        }).catch(() => {});
                    }
                } catch (e) {}
            }

            window.dispatchEvent(new Event("storage"));
        }
        showToast(`Đã xóa yêu cầu phối hợp ${reqId}!`, "info");
    };

