                                                                e.stopPropagation();
                                                                if (e.target.checked) {
                                                                    setSelectedContractIdsForExport(prev => [...prev, contract.id]);
                                                                } else {
                                                                    setSelectedContractIdsForExport(prev => prev.filter(id => id !== contract.id));
                                                                }
